import type { ClientEvent } from "@sazabi/client-sdk-core";
import { AppState, type AppStateStatus } from "react-native";

export interface LifecycleCaptureOptions {
  emit(event: ClientEvent): void;
  /** The app is leaving the foreground: the mobile unload flush point. */
  onBackground(): void;
}

export interface LifecycleCaptureHandle {
  teardown(): void;
}

/**
 * `AppState` is the mobile lifecycle: `background` and `inactive` are the
 * unload, `active` is the return. Each edge is a `lifecycle` row so the
 * timeline reads causally, and leaving the foreground flushes the queue
 * while the OS still allows network activity.
 */
export const installLifecycleCapture = (
  options: LifecycleCaptureOptions,
): LifecycleCaptureHandle => {
  let last: AppStateStatus | undefined = AppState.currentState;

  const onChange = (state: AppStateStatus): void => {
    try {
      if (state === last) return;
      last = state;
      if (
        state !== "active" &&
        state !== "background" &&
        state !== "inactive"
      ) {
        return;
      }
      options.emit({
        type: "lifecycle",
        body: `lifecycle ${state}`,
        severity: "INFO",
        timeUnixMs: Date.now(),
        attributes: { "app.lifecycle.state": state },
      });
      if (state !== "active") {
        options.onBackground();
      }
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  let subscription: { remove(): void } | undefined;
  try {
    subscription = AppState.addEventListener("change", onChange);
  } catch {
    // No AppState on this host: lifecycle rows are simply never emitted.
  }

  return {
    teardown() {
      try {
        subscription?.remove();
      } catch {
        // Best-effort.
      }
    },
  };
};
