import type { ClientEvent } from "@sazabi/client-sdk-core";
import { type CurrentScreen, state } from "./process-state";
import type { NavigationContainerRefLike } from "./types";

// The screen and the emitter live in the process-wide state, so a
// `trackNavigation()` imported from a second copy of the module feeds the
// running instance.

/** The route the user is on, stamped on every row as `app.screen.*`. */
export const getCurrentScreen = (): CurrentScreen => state.screen;

/**
 * Bound at start, cleared at shutdown; navigation tracked before init still
 * updates the screen. `redactUrl` is the core's redaction with the app's
 * `network.redactQueryParams`: a deep-link route path can carry a query
 * string (`/reset-password?token=…`), so it is recorded like any other URL.
 */
export const setNavigationEmitter = (
  emit: ((event: ClientEvent) => void) | undefined,
  redactUrl?: (url: string) => string,
): void => {
  state.navigationEmit = emit;
  state.navigationRedactUrl = redactUrl;
};

const paramKeys = (params: object | undefined): string | undefined => {
  if (!params) return undefined;
  const keys = Object.keys(params);
  return keys.length > 0 ? keys.join(",") : undefined;
};

/**
 * Screen changes come from the navigator the app already owns. Subscribes to
 * a React Navigation container ref's `state` event (expo-router exposes the
 * same ref) and emits a `navigation` row from `getCurrentRoute()`: the route
 * name, the pathname when the router has one, and the param keys, never the
 * values. A state change that lands on the same route (a param update, a
 * nested navigator settling) emits nothing; a new push of the same screen
 * has a new route key and is a new visit. Returns the unsubscribe.
 */
export const trackNavigation = (
  ref: NavigationContainerRefLike,
): (() => void) => {
  const handleState = (): void => {
    try {
      const route = ref.getCurrentRoute();
      if (!route) return;
      const from = state.screen;
      if (
        route.key === from.key &&
        route.name === from.name &&
        route.path === from.path
      ) {
        return;
      }
      state.screen = { name: route.name, path: route.path, key: route.key };
      state.navigationEmit?.({
        type: "navigation",
        body: `navigation ${route.name}`,
        severity: "INFO",
        timeUnixMs: Date.now(),
        attributes: {
          "app.navigation.type": "screen",
          "app.screen.name": route.name,
          "url.path":
            route.path === undefined
              ? undefined
              : (state.navigationRedactUrl?.(route.path) ?? route.path),
          "app.navigation.from": from.name,
          "app.navigation.params": paramKeys(route.params),
        },
      });
    } catch {
      // Capture failures must never surface to the host.
    }
  };

  handleState();
  let unsubscribe: (() => void) | undefined;
  try {
    unsubscribe = ref.addListener("state", handleState);
  } catch {
    // A ref without the event: the initial screen was still recorded.
  }
  return () => {
    try {
      unsubscribe?.();
    } catch {
      // Best-effort.
    }
  };
};

/** Test and shutdown hook: forget the screen so a later init starts clean. */
export const resetNavigationState = (): void => {
  state.screen = {};
  state.navigationEmit = undefined;
  state.navigationRedactUrl = undefined;
};
