import { truncateValue } from "./attributes";
import type { SdkHealthReport } from "./sdk-health";
import type {
  AttributeValue,
  ClientEvent,
  EventAttributes,
  EventSeverity,
} from "./types";

type OtlpAnyValue =
  | { stringValue: string }
  | { intValue: string }
  | { doubleValue: number }
  | { boolValue: boolean };

interface OtlpKeyValue {
  key: string;
  value: OtlpAnyValue;
}

export interface OtlpLogRecord {
  timeUnixNano: string;
  severityNumber: number;
  severityText: EventSeverity;
  body: { stringValue: string };
  attributes: OtlpKeyValue[];
  /** OTLP/JSON encodes trace/span ids as hex (unlike proto3 JSON's base64). */
  traceId?: string;
  spanId?: string;
}

const SEVERITY_NUMBERS: Record<EventSeverity, number> = {
  DEBUG: 5,
  INFO: 9,
  WARN: 13,
  ERROR: 17,
};

const MAX_BODY_LENGTH = 1024;

const encodeValue = (value: AttributeValue): OtlpAnyValue => {
  if (typeof value === "boolean") {
    return { boolValue: value };
  }
  if (typeof value === "number") {
    // proto3 JSON maps int64 to string; doubles stay numeric.
    return Number.isInteger(value)
      ? { intValue: String(value) }
      : { doubleValue: value };
  }
  return { stringValue: truncateValue(value) };
};

const encodeAttributes = (attributes: EventAttributes): OtlpKeyValue[] => {
  const encoded: OtlpKeyValue[] = [];
  for (const [key, value] of Object.entries(attributes)) {
    if (value === undefined) {
      continue;
    }
    encoded.push({ key, value: encodeValue(value) });
  }
  return encoded;
};

export const encodeLogRecord = (
  event: ClientEvent,
  baseAttributes: EventAttributes,
): OtlpLogRecord => {
  const record: OtlpLogRecord = {
    timeUnixNano: `${event.timeUnixMs}000000`,
    severityNumber: SEVERITY_NUMBERS[event.severity],
    severityText: event.severity,
    body: { stringValue: truncateValue(event.body, MAX_BODY_LENGTH) },
    attributes: encodeAttributes({ ...baseAttributes, ...event.attributes }),
  };
  if (event.traceId) {
    record.traceId = event.traceId;
  }
  if (event.spanId) {
    record.spanId = event.spanId;
  }
  return record;
};

/**
 * The slice of `fetch` the transport uses. Declared structurally so the core
 * needs no DOM lib; every host's real `fetch` satisfies it.
 */
export type FetchLike = (
  url: string,
  init: {
    method: "POST";
    headers: Record<string, string>;
    body: string;
    keepalive: boolean;
    /** An `AbortSignal` where the host has `AbortController`; aborts a timed-out upload. */
    signal?: unknown;
  },
) => Promise<unknown>;

/**
 * UTF-8 byte length of a string, without `TextEncoder` (Hermes has none).
 * Request budgets are bytes on the wire; a string's `length` counts UTF-16
 * units and undercounts non-ASCII text up to threefold.
 */
export const utf8Length = (text: string): number => {
  let bytes = text.length;
  for (let index = 0; index < text.length; index += 1) {
    const code = text.charCodeAt(index);
    if (code < 0x80) continue;
    if (code < 0x800) {
      bytes += 1;
    } else if (
      code >= 0xd800 &&
      code <= 0xdbff &&
      (text.charCodeAt(index + 1) & 0xfc00) === 0xdc00
    ) {
      // A surrogate pair: two units, four bytes.
      bytes += 2;
      index += 1;
    } else {
      bytes += 2;
    }
  }
  return bytes;
};

/**
 * Queued-batch uploads allowed in flight at once. A hung intake holds at most
 * this many requests; later batches wait in the capped queue.
 */
const MAX_IN_FLIGHT_UPLOADS = 4;
/** Hard cap on queued bytes, beside `maxQueuedEvents`; the oldest go first. */
const MAX_QUEUED_BYTES = 1_048_576;
/** An upload with no answer after this long counts as a network failure. */
const REQUEST_TIMEOUT_MS = 30_000;
/** Retry pacing: exponential from the base, capped, with jitter. */
const RETRY_BASE_MS = 1_000;
const RETRY_MAX_MS = 60_000;
/** The longest `Retry-After` honored; a longer one waits this long. */
const RETRY_AFTER_MAX_MS = 300_000;
/** Stamped on the first row delivered after events were dropped: how many. */
export const DROPPED_EVENTS_KEY = "app.sdk.dropped_events";
/**
 * Names the sending SDK on every upload, `<package>/<version>`: the input
 * for the intake gateway's per-SDK request label (a separate change), which
 * can then count a request by SDK even when it rejects it before the key is
 * known. The gateway's CORS allow-list admits it, so a browser preflight
 * passes.
 */
export const SDK_HEADER = "x-sazabi-sdk";

export interface TransportOptions {
  /** Full OTLP logs endpoint, e.g. `https://<key>.<region>.intake.<domain>/v1/logs`. */
  url: string;
  publicKey: string;
  resourceAttributes: EventAttributes;
  /** OTLP instrumentation scope: the emitting SDK's name and version. */
  scope: { name: string; version: string };
  /**
   * The fetch to deliver with, captured before the SDK's network patch
   * installs, so exporter traffic can never recurse through our own wrapper
   * or appear in the captured event stream.
   */
  fetchImpl: FetchLike;
  flushIntervalMs: number;
  maxBatchBytes: number;
  maxQueuedEvents: number;
  /** Reports a dropped batch or a full queue; called once per reason. */
  warn?(message: string): void;
  /**
   * The SDK's own delivery health: a batch the intake refused for good
   * (`intake_rejected`, with the status) and uploads that failed on the
   * network before one got through (`intake_unreachable`, with the number
   * of failed tries). The binding turns these into `sdk_health` rows, once
   * per condition per session.
   */
  onHealth?(report: SdkHealthReport): void;
  /**
   * Called when an upload settles with nothing queued, nothing in flight, and
   * every row of the last `snapshotEnvelopes` delivered or refused for good:
   * a saved row evicted from the full queue, or given up by `shutdown()`
   * while the intake was unreachable, keeps it from firing until the next
   * snapshot, so the host's saved copy stays.
   */
  onIdle?(): void;
}

export interface Transport {
  enqueue(record: OtlpLogRecord): void;
  /**
   * Deliver everything queued. `keepalive: true` is for browser unload paths;
   * each request body must stay inside the browser's ~64 KiB keepalive
   * budget, which enqueue-side chunking guarantees via `maxBatchBytes`. Hosts
   * without keepalive ignore the flag.
   */
  flush(options?: { keepalive?: boolean }): Promise<void>;
  /**
   * Encode everything queued into standalone request bodies without sending,
   * leaving the queue empty. The mobile crash outbox persists these and posts
   * them on the next launch; `recordAttributes` are appended to every record
   * (the outbox stamps its replay id there).
   */
  drainEnvelopes(recordAttributes?: EventAttributes): string[];
  /**
   * Encode everything queued into standalone request bodies and keep it
   * queued. `recordAttributes` are stamped on the queued records themselves,
   * so the live upload and the saved copy carry the same values (the mobile
   * SDK saves its queue this way when the app leaves the foreground). Rows an
   * earlier snapshot saved whose upload is still in flight are included as
   * they were sent: the copy this one replaces held them.
   */
  snapshotEnvelopes(recordAttributes: EventAttributes): string[];
  /**
   * While held, `enqueue` never flushes on its own, neither on the byte
   * budget nor by scheduling the timer: the mobile crash path holds the
   * transport while it stamps the fatal row and everything buffered before
   * it, then drains the whole batch into the outbox. Without this, a fatal
   * row that tips the queue over the budget would be flushed out of the queue
   * into a request the dying process never completes.
   */
  holdFlushes(hold: boolean): void;
  /**
   * Deliver a previously drained envelope. Resolves `true` once the envelope
   * is settled: the intake accepted it (2xx) or refused it for good (a 4xx
   * other than 408 and 429, dropped with a warning). Resolves `false` when it
   * is worth sending again (408, 429, 5xx, a network failure, a timeout), and
   * never rejects, so a persisted envelope is deleted only once settled.
   */
  sendEnvelope(body: string): Promise<boolean>;
  shutdown(): Promise<void>;
}

interface QueuedRecord {
  record: OtlpLogRecord;
  bytes: number;
  /** Enqueue order: failed batches merge back by it, so eviction stays oldest-first. */
  seq: number;
  /** Stamped by `snapshotEnvelopes`: the host holds a saved copy of this row. */
  saved?: boolean;
}

type Outcome =
  | { kind: "sent" }
  /** `network` marks a failure with no answer at all: a dropped connection or a timeout. */
  | { kind: "retry"; retryAfterMs?: number; network?: true }
  | { kind: "drop" | "split"; status: number };

const RETRY: Outcome = { kind: "retry", network: true };

/** `Retry-After` as delta-seconds or an HTTP date, in ms; undefined when absent. */
const retryAfterMs = (response: unknown): number | undefined => {
  try {
    const raw = (
      response as { headers?: { get?(name: string): string | null } }
    ).headers?.get?.("retry-after");
    if (!raw) return undefined;
    const seconds = Number(raw);
    const ms = Number.isFinite(seconds)
      ? seconds * 1_000
      : Date.parse(raw) - Date.now();
    return ms > 0 ? Math.min(ms, RETRY_AFTER_MAX_MS) : undefined;
  } catch {
    return undefined;
  }
};

/**
 * A host fetch answers with a Response-like whose `status` tells what the
 * intake did with the batch; a host that answers with something else (a bare
 * promise from an unusual fetch) is trusted, as it always was.
 */
const classify = (response: unknown): Outcome => {
  const status = (response as { status?: unknown } | null)?.status;
  if (typeof status !== "number" || (status >= 200 && status < 300)) {
    return { kind: "sent" };
  }
  if (status === 408 || status === 429 || status >= 500) {
    return { kind: "retry", retryAfterMs: retryAfterMs(response) };
  }
  return { kind: status === 413 ? "split" : "drop", status };
};

export const createTransport = (options: TransportOptions): Transport => {
  const queue: QueuedRecord[] = [];
  let queuedBytes = 0;
  let nextRecordSeq = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let shutDown = false;
  let held = false;
  // Queued-batch uploads still open; each removes itself when it settles.
  const inFlight = new Set<Promise<void>>();
  // The rows of those uploads, for the next snapshot.
  const sending = new Set<QueuedRecord[]>();
  // A row of the last snapshot was lost undelivered: onIdle stays quiet.
  let savedLost = false;
  // Events dropped since the last delivered row said so.
  let dropped = 0;
  // Backoff after a retryable failure: nothing queued is sent before
  // `retryAt` except by shutdown() or an unload flush.
  let attempt = 0;
  let retryAt = 0;
  // Backoff windows opened by a failure with no answer from the intake
  // since it last answered anything (concurrent failures count once).
  let unreachableAttempts = 0;
  const warned = new Set<string>();

  const report = (health: SdkHealthReport): void => {
    try {
      options.onHealth?.(health);
    } catch {
      // Never throw into the host.
    }
  };

  const warnOnce = (reason: string, message: string): void => {
    if (warned.has(reason)) return;
    warned.add(reason);
    try {
      options.warn?.(message);
    } catch {
      // Never throw into the host.
    }
  };

  const buildEnvelope = (records: OtlpLogRecord[]): string =>
    JSON.stringify({
      resourceLogs: [
        {
          resource: {
            attributes: encodeAttributes(options.resourceAttributes),
          },
          scopeLogs: [
            {
              scope: {
                name: options.scope.name,
                version: options.scope.version,
              },
              logRecords: records,
            },
          ],
        },
      ],
    });

  const envelopeOverhead = utf8Length(buildEnvelope([])) + 64;
  const chunkBudget = Math.max(4096, options.maxBatchBytes - envelopeOverhead);

  const clearTimer = (): void => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };

  // The flush interval, or the end of a backoff when one is running.
  const scheduleFlush = (): void => {
    if (timer !== undefined || shutDown) {
      return;
    }
    const wait = retryAt - Date.now();
    timer = setTimeout(
      () => {
        timer = undefined;
        void flush();
      },
      wait > 0 ? wait : options.flushIntervalMs,
    );
  };

  // Oldest first, counted: a long offline period keeps the newest events
  // within both caps and says how many it lost. enqueue() refuses a record
  // larger than the byte cap, so this never empties the queue on bytes.
  const evict = (): void => {
    while (
      queue.length > options.maxQueuedEvents ||
      queuedBytes > MAX_QUEUED_BYTES
    ) {
      const removed = queue.shift() as QueuedRecord;
      queuedBytes -= removed.bytes;
      dropped += 1;
      if (removed.saved) savedLost = true;
      warnOnce(
        "full",
        "the event queue is full (is the device offline?); dropping the oldest events.",
      );
    }
  };

  // At most `limit` chunks of `rows`, oldest records first.
  const chunksOf = (rows: QueuedRecord[], limit: number): QueuedRecord[][] => {
    const chunks: QueuedRecord[][] = [];
    if (limit <= 0) {
      return chunks;
    }
    let current: QueuedRecord[] = [];
    let currentBytes = 0;

    for (const queued of rows) {
      if (current.length > 0 && currentBytes + queued.bytes > chunkBudget) {
        chunks.push(current);
        current = [];
        currentBytes = 0;
        if (chunks.length >= limit) {
          break;
        }
      }
      current.push(queued);
      currentBytes += queued.bytes;
    }
    if (current.length > 0) {
      chunks.push(current);
    }
    return chunks;
  };

  // The same chunks, taken out of the queue; whatever does not fit stays.
  const takeChunks = (limit: number): QueuedRecord[][] => {
    const chunks = chunksOf(queue, limit);
    let taken = 0;
    for (const chunk of chunks) taken += chunk.length;
    for (const removed of queue.splice(0, taken)) {
      queuedBytes -= removed.bytes;
    }
    return chunks;
  };

  // A record with `extra` set, replacing any value it already had for a key.
  const stamped = (
    record: OtlpLogRecord,
    extra: OtlpLogRecord["attributes"],
  ): OtlpLogRecord =>
    extra.length === 0
      ? record
      : {
          ...record,
          attributes: [
            ...record.attributes.filter(
              (attribute) => !extra.some(({ key }) => key === attribute.key),
            ),
            ...extra,
          ],
        };

  // The records of a chunk, the first carrying the drop count when there is
  // one; `count` is what the caller must give back if the rows never land.
  const recordsOf = (
    chunk: QueuedRecord[],
  ): { records: OtlpLogRecord[]; count: number } => {
    const records = chunk.map((queued) => queued.record);
    const count = dropped;
    const first = records[0];
    if (count > 0 && first) {
      dropped = 0;
      records[0] = {
        ...first,
        attributes: [
          ...first.attributes,
          { key: DROPPED_EVENTS_KEY, value: { intValue: String(count) } },
        ],
      };
    }
    return { records, count: first ? count : 0 };
  };

  const post = (body: string, keepalive = false): Promise<Outcome> => {
    const Abort = (globalThis as { AbortController?: new () => unknown })
      .AbortController;
    let controller: { signal?: unknown; abort?(): void } | undefined;
    let request: Promise<unknown>;
    try {
      controller = Abort ? (new Abort() as typeof controller) : undefined;
      request = options.fetchImpl(options.url, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          authorization: `Bearer ${options.publicKey}`,
          [SDK_HEADER]: `${options.scope.name}/${options.scope.version}`,
        },
        body,
        keepalive,
        signal: controller?.signal,
      });
    } catch {
      // A fetch that throws synchronously must not reject out of flush():
      // the SDK would capture its own unhandled rejection, enqueue it, and
      // fail again on the next flush.
      return Promise.resolve(RETRY);
    }
    return new Promise((resolve) => {
      // A hung intake frees the slot: the batch is retried like a failure.
      const timeout = setTimeout(() => {
        try {
          controller?.abort?.();
        } catch {
          // Best-effort.
        }
        resolve(RETRY);
      }, REQUEST_TIMEOUT_MS);
      void Promise.resolve(request)
        .then(classify, () => RETRY)
        .then((outcome) => {
          clearTimeout(timeout);
          resolve(outcome);
        });
    });
  };

  const backingOff = (): boolean => Date.now() < retryAt;

  // Rows that did not land go back in enqueue order, wherever they sit
  // among rows restored by other uploads, so evict() still drops the oldest.
  const restore = (chunk: QueuedRecord[]): void => {
    queue.push(...chunk);
    queue.sort((a, b) => a.seq - b.seq);
    for (const queued of chunk) queuedBytes += queued.bytes;
    evict();
  };

  const backOff = (retryAfter: number | undefined, network: boolean): void => {
    const now = Date.now();
    // Concurrent uploads failing together are one failure, not four.
    if (now >= retryAt) {
      attempt += 1;
      if (network) unreachableAttempts += 1;
    }
    const ceiling = Math.min(RETRY_MAX_MS, RETRY_BASE_MS * 2 ** (attempt - 1));
    const delay = Math.max(
      retryAfter ?? 0,
      ceiling / 2 + (Math.random() * ceiling) / 2,
    );
    retryAt = Math.max(retryAt, now + delay);
    clearTimer();
    scheduleFlush();
  };

  /**
   * One delivery attempt and what its answer means: 2xx is done; 408, 429,
   * 5xx, a network failure, and a timeout put the rows back in the queue in
   * enqueue order behind a backoff (the caps still apply); 413 halves the batch
   * and tries each half, putting a half back in the queue instead when a
   * backoff started meanwhile (outside an unload flush or shutdown); any
   * other 4xx, or a single row too large to send, drops the rows with one
   * warning per status. Nothing is retried after shutdown().
   */
  const deliver = async (
    chunk: QueuedRecord[],
    keepalive: boolean,
  ): Promise<void> => {
    const { records, count } = recordsOf(chunk);
    const outcome = await post(buildEnvelope(records), keepalive);
    // Any answer, a refusal included, ends an outage: what it took to get
    // through is reported now, not merged into a later one.
    if (
      unreachableAttempts > 0 &&
      (outcome.kind !== "retry" || outcome.network !== true)
    ) {
      const attempts = unreachableAttempts;
      unreachableAttempts = 0;
      report({
        diagnostic: "intake_unreachable",
        attributes: { "app.sdk.attempts": attempts },
      });
    }
    if (outcome.kind === "sent") {
      attempt = 0;
      return;
    }
    dropped += count;
    if (outcome.kind === "split" && chunk.length > 1) {
      const half = Math.ceil(chunk.length / 2);
      for (const part of [chunk.slice(0, half), chunk.slice(half)]) {
        // A 429 on the first half (or on any other upload) means wait: the
        // rest goes back to the queue for the timer to send.
        if (!keepalive && !shutDown && backingOff()) {
          restore(part);
          scheduleFlush();
        } else {
          await deliver(part, keepalive);
        }
      }
      return;
    }
    if (outcome.kind === "retry") {
      if (shutDown) {
        if (chunk.some((queued) => queued.saved)) savedLost = true;
        return;
      }
      restore(chunk);
      backOff(outcome.retryAfterMs, outcome.network === true);
      return;
    }
    dropped += chunk.length;
    warnOnce(
      String(outcome.status),
      `the intake refused a batch with HTTP ${outcome.status}; dropped ${chunk.length} event(s).`,
    );
    report({
      diagnostic: "intake_rejected",
      attributes: { "app.sdk.http_status": outcome.status },
    });
  };

  // Every upload gets a sequence number so a flush() can wait for exactly
  // the uploads started while it waited, and no others: an older upload
  // that never answers holds its slot, not every later caller.
  let nextUploadSeq = 0;
  const uploadsBySeq = new Map<number, Promise<void>>();
  const startUpload = (chunk: QueuedRecord[], keepalive: boolean) => {
    const seq = nextUploadSeq;
    nextUploadSeq += 1;
    const upload: Promise<void> = deliver(chunk, keepalive).then(() => {
      inFlight.delete(upload);
      sending.delete(chunk);
      uploadsBySeq.delete(seq);
      if (queue.length === 0 && inFlight.size === 0 && !savedLost) {
        try {
          options.onIdle?.();
        } catch {
          // Never throw into the host.
        }
      }
    });
    inFlight.add(upload);
    sending.add(chunk);
    uploadsBySeq.set(seq, upload);
    return upload;
  };

  // One shared loop drains the queue: it keeps at most MAX_IN_FLIGHT_UPLOADS
  // requests open, refills each slot as soon as any upload settles (so one
  // hung upload holds only its own slot), and ends once everything queued
  // has been started or a failure started a backoff. Every flush() while it
  // runs joins this loop instead of attaching another waiter to the same
  // hung uploads, so a stalled intake never grows memory beyond the capped
  // queue.
  let draining: Promise<void> | null = null;
  const drainQueue = async (): Promise<void> => {
    while (!backingOff()) {
      for (const chunk of takeChunks(MAX_IN_FLIGHT_UPLOADS - inFlight.size)) {
        startUpload(chunk, false);
      }
      if (queue.length === 0) break;
      // A non-empty queue always fills a free slot, so `inFlight` is never
      // empty here.
      await Promise.race(inFlight);
    }
  };

  const flush = async (flushOptions?: {
    keepalive?: boolean;
  }): Promise<void> => {
    clearTimer();
    const keepalive = flushOptions?.keepalive === true;

    // An unload flush is the page's last chance and goes out whole, backoff
    // or not, and so does the one shutdown() makes; any other flush joins
    // the shared drain loop and resolves once the uploads started during its
    // wait have settled. During a backoff it sends nothing: the timer
    // retries when the backoff ends.
    if (keepalive || shutDown) {
      await Promise.all(
        takeChunks(Number.POSITIVE_INFINITY).map((chunk) =>
          startUpload(chunk, keepalive),
        ),
      );
      return;
    }
    const firstSeq = nextUploadSeq;
    while (queue.length > 0 && !backingOff()) {
      if (draining === null) {
        draining = drainQueue().finally(() => {
          draining = null;
        });
      }
      await draining;
    }
    if (queue.length > 0) scheduleFlush();
    const mine: Promise<void>[] = [];
    for (const [seq, upload] of uploadsBySeq) {
      if (seq >= firstSeq) mine.push(upload);
    }
    await Promise.all(mine);
  };

  return {
    enqueue(record) {
      if (shutDown) {
        return;
      }
      const bytes = utf8Length(JSON.stringify(record)) + 1;
      // One record with hundreds of long attributes can outgrow the byte cap
      // alone: it is dropped and counted, never buffered above the cap.
      if (bytes > MAX_QUEUED_BYTES) {
        dropped += 1;
        warnOnce(
          "oversized",
          "dropped an event larger than the 1 MiB queue limit.",
        );
        return;
      }
      queue.push({ record, bytes, seq: nextRecordSeq });
      nextRecordSeq += 1;
      queuedBytes += bytes;
      evict();

      if (held) {
        return;
      }
      if (queuedBytes >= chunkBudget && !backingOff()) {
        void flush();
      } else {
        scheduleFlush();
      }
    },
    flush,
    drainEnvelopes(recordAttributes) {
      clearTimer();
      const extra = recordAttributes ? encodeAttributes(recordAttributes) : [];
      return takeChunks(Number.POSITIVE_INFINITY).map((chunk) => {
        const { records } = recordsOf(chunk);
        return buildEnvelope(records.map((record) => stamped(record, extra)));
      });
    },
    snapshotEnvelopes(recordAttributes) {
      const extra = encodeAttributes(recordAttributes);
      savedLost = false;
      for (const queued of queue) {
        queued.record = stamped(queued.record, extra);
        const bytes = utf8Length(JSON.stringify(queued.record)) + 1;
        queuedBytes += bytes - queued.bytes;
        queued.bytes = bytes;
        queued.saved = true;
      }
      // A second snapshot while the first one's uploads are out (iOS goes
      // inactive, then background) must not drop their rows from the copy.
      const rows = new Set(queue);
      for (const chunk of sending) {
        for (const queued of chunk) if (queued.saved) rows.add(queued);
      }
      return chunksOf(
        [...rows].sort((a, b) => a.seq - b.seq),
        Number.POSITIVE_INFINITY,
      ).map((chunk) => buildEnvelope(chunk.map((queued) => queued.record)));
    },
    holdFlushes(hold) {
      held = hold;
    },
    async sendEnvelope(body) {
      const outcome = await post(body);
      if (outcome.kind === "retry") return false;
      if (outcome.kind !== "sent") {
        warnOnce(
          String(outcome.status),
          `the intake refused a stored crash report with HTTP ${outcome.status}; dropped it.`,
        );
        report({
          diagnostic: "intake_rejected",
          attributes: { "app.sdk.http_status": outcome.status },
        });
      }
      return true;
    },
    async shutdown() {
      shutDown = true;
      await flush();
    },
  };
};
