// The props `<SazabiRoot>` reads off the touched element's fiber, typed on
// the components that take them: every `View`, `Pressable` (its props extend
// `ViewProps`), `Text`, and the `Touchable*` family. Shipped in the published
// declarations, so `<Pressable sazabiName="Pay now">` type-checks with no
// setup.
declare module "react-native" {
  interface ViewProps {
    /** Names this element in touch rows (`app.widget.name`), ahead of `accessibilityLabel` and `testID`. */
    sazabiName?: string;
    /** Keeps the name of this element and everything inside it out of touch rows. */
    sazabiMask?: boolean;
  }
  interface TextProps {
    /** Names this element in touch rows (`app.widget.name`), ahead of `accessibilityLabel` and `testID`. */
    sazabiName?: string;
    /** Keeps the name of this element and everything inside it out of touch rows. */
    sazabiMask?: boolean;
  }
  interface TouchableWithoutFeedbackProps {
    /** Names this element in touch rows (`app.widget.name`), ahead of `accessibilityLabel` and `testID`. */
    sazabiName?: string;
    /** Keeps the name of this element and everything inside it out of touch rows. */
    sazabiMask?: boolean;
  }
}
export { SDK_VERSION } from "./version";

const DEFAULT_FLUSH_INTERVAL_MS = 5_000;
const DEFAULT_MAX_BATCH_BYTES = 57_344;
const DEFAULT_MAX_QUEUED_EVENTS = 500;
/** Events captured before persisted session state is read are held here. */
const MAX_PRE_SESSION_EVENTS = 200;
const DEFAULT_REQUEST_ID_HEADERS = [
  "x-request-id",
  "cf-ray",
  "x-vercel-id",
  "x-amz-cf-id",
  "fly-request-id",
];
/** Keys the session machine persists through the storage adapter. */
const PERSISTED_SESSION_KEYS = ["sazabi.session", "sazabi.distinctId"];
/**
 * How long a process must outlive a fatal error before it uploads the crash
 * outbox itself. React Native kills the process shortly after the handler
 * returns; anything the dying process sent could not be cleared, and the next
 * launch would send it again. A process still running after this long (a
 * development build, a handler that does not terminate) delivers the outbox
 * itself; otherwise the next launch does.
 */
const FATAL_SURVIVAL_MS = 2_000;
/**
 * `telemetry.sdk.language`. The OpenTelemetry well-known values name a
 * runtime as well as a language (`webjs` is JavaScript in a browser, `nodejs`
 * is Node.js), and neither describes Hermes or JavaScriptCore inside a React
 * Native app; the semantic conventions allow a custom value when no listed
 * one applies.
 */
const SDK_LANGUAGE = "javascript";

/**
 * What happened between `init()` and the session existing, in order: events
 * wait with the identity changes around them, so a sign-out and sign-in
 * during a slow storage read still put each row under the right user and
 * session when the queue replays.
 */
type PreSessionOp =
  | { kind: "event"; event: ClientEvent; screen: CurrentScreen }
  | { kind: "identify"; distinctId: string }
  | { kind: "reset" };

const identifyEvent = (
  distinctId: string,
  traits: Record<string, unknown> | undefined,
): ClientEvent => ({
  type: "custom",
  body: `identify ${distinctId}`,
  severity: "INFO",
  timeUnixMs: Date.now(),
  attributes: {
    "app.custom.name": "identify",
    ...(traits ? flattenAttributes(traits, "custom") : {}),
  },
});

const start = (config: ReactNativeSdkConfig): void => {
  // Bound before capture activates. React Native's fetch rides XMLHttpRequest,
  // which the dormant patch may already wrap; intake URLs take its internal
  // passthrough branch, so transport traffic never recurses into capture.
  const hostFetch = (globalThis as { fetch?: FetchLike }).fetch;
  if (typeof hostFetch !== "function") {
    return;
  }
  const prePatchFetch: FetchLike = (url, init) => hostFetch(url, init);

  const endpoint = resolveIntakeEndpoint(config);
  if (!endpoint) {
    return;
  }
  const intakeUrl = `${endpoint.baseUrl}/v1/logs`;
  const randomBytes = createRandomBytes();
  const storage = config.storage;
  // The prefix keeps the console mirror from recording the SDK's own line.
  const warn = (message: string): void =>
    console.warn(`${SDK_CONSOLE_PREFIX} ${message}`);

  const transport = createTransport({
    url: intakeUrl,
    publicKey: endpoint.publicKey,
    resourceAttributes: {
      "service.name": config.serviceName,
      "service.version": config.serviceVersion,
      "deployment.environment": config.environment,
      "telemetry.sdk.name": SDK_NAME,
      "telemetry.sdk.version": SDK_VERSION,
      "telemetry.sdk.language": SDK_LANGUAGE,
      ...hostResourceAttributes(),
    },
    scope: { name: SDK_NAME, version: SDK_VERSION },
    fetchImpl: prePatchFetch,
    flushIntervalMs: config.flushIntervalMs ?? DEFAULT_FLUSH_INTERVAL_MS,
    maxBatchBytes: config.maxBatchBytes ?? DEFAULT_MAX_BATCH_BYTES,
    maxQueuedEvents: config.maxQueuedEvents ?? DEFAULT_MAX_QUEUED_EVENTS,
    warn,
    // The intake refused a batch, or was unreachable for a while: one
    // `sdk_health` row per condition per launch (defined below; the
    // transport reports only from settled uploads, after start() returns).
    onHealth: (report) => reportHealth(report),
    // Everything queued, and every row the last save holds, has been
    // delivered: the copy saved when the app last left the foreground has
    // nothing left to replay. Only this transport's own copy goes.
    onIdle: () => {
      if (storage) clearQueue(storage, transport);
    },
  });

  // Session state lives behind the storage adapter, which may be
  // asynchronous. Capture installs now; events emitted before the persisted
  // state is read wait here and are stamped once the session exists, so a
  // cold start never splits its first seconds into a throwaway session.
  let session: SessionManager | undefined;
  const preSessionOps: PreSessionOp[] = [];
  let preSessionEventCount = 0;
  // Set by shutdown() once its synchronous teardowns have run: a callback
  // that outlives them (a slow response's loadend, a navigator event) must
  // not touch the session store for a row the stopped transport would drop
  // anyway, while the teardowns themselves (the tracker closing a touch
  // that is still down) still get their final rows out.
  let stopped = false;

  const networkConfig: NetworkCaptureConfig = config.network ?? {};
  // The route path is recorded under the same rule as request URLs: a
  // deep link's `?token=…` never leaves the device in plain text.
  const redactScreenUrl = (url: string): string =>
    redactUrl(url, networkConfig.redactQueryParams);

  // `screen` is the one the event happened on: a buffered event replayed
  // after a slow storage read must not take the screen the app moved to.
  const stamp = (
    event: ClientEvent,
    active: SessionManager,
    screen: CurrentScreen = getCurrentScreen(),
  ): void => {
    active.touch();
    const base: EventAttributes = {
      "app.event_type": event.type,
      "session.id": active.getSessionId(),
      "session.window_id": active.getWindowId(),
      "session.distinct_id": active.getDistinctId(),
      "app.screen.name": screen.name,
      "app.screen.url":
        screen.path === undefined ? undefined : redactScreenUrl(screen.path),
      "derived.source": "sdk",
    };
    transport.enqueue(encodeLogRecord(event, base));
  };

  const warnedBeforeSend = new Set<string>();
  const warnBeforeSendOnce = (warning: {
    reason: string;
    message: string;
  }): void => {
    if (warnedBeforeSend.has(warning.reason)) return;
    warnedBeforeSend.add(warning.reason);
    const { message } = warning;
    warn(message);
  };
  const beforeSend = createBeforeSendGate(
    config.beforeSend,
    warnBeforeSendOnce,
  );

  const emit = (captured: ClientEvent): void => {
    if (stopped) {
      return;
    }
    try {
      const event = beforeSend(captured);
      if (!event) {
        return;
      }
      if (session) {
        stamp(event, session);
      } else if (
        preSessionEventCount < MAX_PRE_SESSION_EVENTS ||
        // At most one per diagnostic, and already marked reported: a full
        // pre-session queue must not swallow the launch's only health row.
        event.type === "sdk_health"
      ) {
        preSessionOps.push({
          kind: "event",
          event,
          screen: getCurrentScreen(),
        });
        preSessionEventCount += 1;
      }
    } catch {
      // Emitting must never throw into the host.
    }
  };

  const safeEmitEvent = (build: () => ClientEvent): void => {
    try {
      emit(build());
    } catch {
      // Never throw into the host.
    }
  };

  // The SDK's own delivery health as `sdk_health` rows, at most one per
  // condition per launch, so a refused health row is never reported again.
  const reportHealth = createSdkHealthReporter(emit);

  // Read the stored crash outbox before anything can crash: a synchronous
  // adapter is merged by the time this returns, so a fatal error at any later
  // point extends the stored report instead of writing beside it. What the
  // read discards is reported on this launch.
  if (storage) {
    watchOutbox(storage, reportHealth);
    void loadOutbox(storage, warn);
  }

  // The intake, and in development the Metro server (LogBox symbolication,
  // bundle and status requests), are never app traffic.
  const devServer = devServerOrigin();
  // Matched by parsed origin and whole path segments, never a string prefix:
  // `https://<intake>.evil.test/` is app traffic.
  const isInternalUrl = (url: string): boolean =>
    isUnderBase({ url, base: endpoint.baseUrl }) ||
    (devServer !== undefined && isUnderBase({ url, base: devServer })) ||
    (isDevHost() && url.includes("/symbolicate"));

  const teardowns: Array<() => void> = [];
  if (storage) teardowns.push(() => unwatchOutbox(storage, reportHealth));
  // Set by a fatal error: from then on this process uploads no outbox until
  // it has outlived FATAL_SURVIVAL_MS.
  let survivalTimer: ReturnType<typeof setTimeout> | undefined;
  let crashed = false;
  teardowns.push(() => {
    if (survivalTimer !== undefined) clearTimeout(survivalTimer);
    survivalTimer = undefined;
  });

  const errorCapture = installErrorCapture({
    emit,
    unhandledRejections: config.errors?.unhandledRejections !== false,
    previousRejectionTracker: config.errors?.previousRejectionTracker,
    onFatal: (fatalEvent) => {
      crashed = true;
      // Nothing may leave the queue on its own until the outbox has it: a
      // fatal row that tips the queue over the byte budget would otherwise
      // be flushed into a request the dying process never completes.
      transport.holdFlushes(true);
      try {
        // A crash before the persisted session was read: the buffered rows
        // would die with the process. Start the session from whatever has
        // been read so far and stamp them now; continuity with the previous
        // launch is lost in that window, the crash is not.
        startSession();
        emit(fatalEvent);
        if (storage) {
          stashOutbox(storage, transport, randomHex(randomBytes, 8));
        }
      } finally {
        transport.holdFlushes(false);
      }
      if (!storage) {
        void transport.flush();
        return;
      }
      if (survivalTimer === undefined && !stopped) {
        survivalTimer = setTimeout(() => {
          survivalTimer = undefined;
          void deliverOutbox(storage, transport);
        }, FATAL_SURVIVAL_MS);
      }
    },
  });
  teardowns.push(() => errorCapture.teardown());

  if (config.pointer?.capture !== false) {
    const tracker = createPointerTracker({
      emit,
      randomBytes,
      sampleIntervalMs: config.pointer?.sampleIntervalMs,
      partialIntervalMs: config.pointer?.partialIntervalMs,
    });
    setActiveTracker(tracker);
    teardowns.push(() => {
      setActiveTracker(undefined);
      tracker.teardown();
    });
  }

  setNavigationEmitter(emit, redactScreenUrl);
  teardowns.push(() => setNavigationEmitter(undefined));

  if (config.console?.capture !== false) {
    const consoleCapture = installConsoleCapture({
      emit,
      levels: config.console?.levels ?? ["error", "warn"],
      selfPrefix: SDK_CONSOLE_PREFIX,
    });
    teardowns.push(() => consoleCapture.teardown());
  }

  const networkCapture = networkConfig.capture ?? true;
  const propagateTraceContext = networkConfig.propagateTraceContext ?? true;
  if (networkCapture || propagateTraceContext) {
    const network = installNetworkCapture({
      emit,
      traceContext: createTraceContextManager({
        sampledFlag: networkConfig.sampledFlag ?? false,
        randomBytes,
      }),
      capture: networkCapture,
      propagateTraceContext,
      allowlist: networkConfig.allowlist ?? [],
      redactQueryParams: networkConfig.redactQueryParams,
      requestIdHeaders:
        networkConfig.requestIdHeaders ?? DEFAULT_REQUEST_ID_HEADERS,
      isInternalUrl,
      resolveUrl,
      // No origin and no CORS preflight on a native host: every request is
      // a correlation candidate unless the allowlist narrows it.
      isDefaultInjectionTarget: () => true,
    });
    teardowns.push(() => network.teardown());
  }

  const lifecycle = installLifecycleCapture({
    emit,
    onBackground: () => {
      // The OS may kill a backgrounded app without another callback: what
      // is queued (all of it, offline) is saved for the next launch first.
      if (storage) saveQueue(storage, transport, randomHex(randomBytes, 8));
      void transport.flush();
    },
  });
  teardowns.push(() => lifecycle.teardown());

  // Session store: hydrated from the adapter when there is one, memory only
  // otherwise. The window id is one app launch either way.
  let sessionStore: SessionStore;
  let ready: Promise<void>;
  if (storage) {
    const hydrating = createHydratingStore(storage, PERSISTED_SESSION_KEYS);
    sessionStore = hydrating.store;
    ready = hydrating.ready;
  } else {
    sessionStore = createMemoryStore();
    ready = Promise.resolve();
  }

  const startSession = (): void => {
    // A hydration that lands after shutdown() starts nothing: no session
    // write, no outbox upload, and the identity claimed for a later init()
    // stays where it is.
    if (session || stopped) {
      return;
    }
    const active = createSessionManager({
      store: sessionStore,
      windowStore: createMemoryStore(),
      randomBytes,
    });
    session = active;
    // Identity claimed before init() comes first: it never produced a row.
    if (state.pendingReset) {
      active.reset();
      state.pendingReset = false;
    }
    const claimedBeforeInit = state.pendingIdentity;
    state.pendingIdentity = undefined;
    if (claimedBeforeInit) {
      active.setDistinctId(claimedBeforeInit.distinctId);
      emit(
        identifyEvent(claimedBeforeInit.distinctId, claimedBeforeInit.traits),
      );
    }
    // Then everything since init(), in the order it happened.
    for (const op of preSessionOps.splice(0)) {
      try {
        if (op.kind === "identify") {
          active.setDistinctId(op.distinctId);
        } else if (op.kind === "reset") {
          active.reset();
        } else {
          stamp(op.event, active, op.screen);
        }
      } catch {
        // Never throw into the host.
      }
    }
    if (storage && !crashed) {
      void deliverOutbox(storage, transport);
    }
  };

  // Identity changes with no event between them collapse to their net effect
  // (a reset if there was one, then the last identify after it), so a loop of
  // identify() calls during a slow storage read cannot grow the queue: with
  // no row stamped in between, the skipped steps change nothing visible.
  const queueIdentity = (op: PreSessionOp): void => {
    let runStart = preSessionOps.length;
    while (runStart > 0 && preSessionOps[runStart - 1]?.kind !== "event") {
      runStart -= 1;
    }
    const run = preSessionOps.splice(runStart);
    if (op.kind === "reset" || run.some((queued) => queued.kind === "reset")) {
      preSessionOps.push({ kind: "reset" });
    }
    if (op.kind === "identify") {
      preSessionOps.push(op);
    }
  };

  state.instance = {
    identify(distinctId, traits) {
      safeEmitEvent(() => {
        if (session) {
          session.setDistinctId(distinctId);
        } else {
          queueIdentity({ kind: "identify", distinctId });
        }
        return identifyEvent(distinctId, traits);
      });
    },
    reset() {
      try {
        if (session) {
          session.reset();
        } else {
          queueIdentity({ kind: "reset" });
        }
      } catch {
        // Never throw into the host.
      }
    },
    addEvent(name, attributes) {
      safeEmitEvent(() => ({
        type: "custom",
        body: `custom ${name}`,
        severity: "INFO",
        timeUnixMs: Date.now(),
        attributes: {
          "app.custom.name": name,
          ...(attributes ? flattenAttributes(attributes, "custom") : {}),
        },
      }));
    },
    log(severity, message, metadata) {
      safeEmitEvent(() => ({
        type: "log",
        body: message,
        severity,
        timeUnixMs: Date.now(),
        attributes: metadata ? flattenAttributes(metadata) : {},
      }));
    },
    async flush() {
      await ready;
      await transport.flush();
    },
    async shutdown() {
      for (const teardown of teardowns.reverse()) {
        try {
          teardown();
        } catch {
          // Teardown must be best-effort.
        }
      }
      stopped = true;
      uninstallNetworkPatches();
      resetNavigationState();
      await ready;
      await transport.shutdown();
    },
  };

  void ready.then(startSession, startSession);
};

/** `init()` must never throw into the app, whatever a hostile host does. */
const safeStart = (config: ReactNativeSdkConfig): void => {
  try {
    start(config);
  } catch {
    // Capture that could not install stays off.
  }
};

/**
 * Initialize the SDK. Idempotent: repeat calls are ignored. Installs nothing
 * under react-native-web (use `@sazabi/browser` there). When `consent` is
 * provided, nothing is installed until it resolves true.
 */
export const init = (config: ReactNativeSdkConfig): void => {
  if (isWebHost()) {
    if (!state.warnedWebHost) {
      state.warnedWebHost = true;
      console.warn(
        `${SDK_CONSOLE_PREFIX} this app is running in a browser; use @sazabi/browser instead. SDK disabled.`,
      );
    }
    return;
  }
  if (state.initialized) {
    return;
  }
  state.initialized = true;
  state.generation += 1;
  const thisGeneration = state.generation;

  if (!config.serviceName || !resolveIntakeEndpoint(config)) {
    console.warn(
      `${SDK_CONSOLE_PREFIX} init() requires intakeUrl and serviceName; SDK disabled. ` +
        "Pass publicKey too if the intake URL is a proxy that carries no key.",
    );
    return;
  }

  if (config.consent === undefined) {
    safeStart(config);
    return;
  }

  try {
    void Promise.resolve(config.consent())
      .then((granted) => {
        // A consent that lands after shutdown(), or after a later init(),
        // belongs to an initialization that no longer exists.
        if (granted === true && thisGeneration === state.generation) {
          safeStart(config);
        }
      })
      .catch(() => {
        // Consent evaluation failed: stay dormant.
      });
  } catch {
    // Synchronous throw from consent(): stay dormant.
  }
};

/** Set the client-asserted user identity (`session.distinct_id`). */
export const identify = (
  distinctId: string,
  traits?: Record<string, unknown>,
): void => {
  if (state.instance) {
    state.instance.identify(distinctId, traits);
  } else {
    state.pendingIdentity = { distinctId, traits };
  }
};

/**
 * Logout: clear the client-asserted identity and rotate both session and
 * window ids, so later activity on this device never threads into the
 * previous user's timeline.
 */
export const reset = (): void => {
  if (state.instance) {
    state.instance.reset();
  } else {
    state.pendingReset = true;
    state.pendingIdentity = undefined;
  }
};

/** Emit a custom mark into the session event stream. */
export const addEvent = (
  name: string,
  attributes?: Record<string, unknown>,
): void => {
  state.instance?.addEvent(name, attributes);
};

/**
 * Emit an application log line (`app.event_type: "log"`) with session context
 * attached. Drops silently before init/consent, like all capture.
 */
export const log = (
  severity: EventSeverity,
  message: string,
  metadata?: Record<string, unknown>,
): void => {
  state.instance?.log(severity, message, metadata);
};

/** Force-flush queued events. */
export const flush = async (): Promise<void> => {
  await state.instance?.flush();
};

/** Tear down all patches/listeners (restoring originals) and flush. */
export const shutdown = async (): Promise<void> => {
  const active = state.instance;
  state.instance = undefined;
  state.initialized = false;
  state.generation += 1;
  state.pendingIdentity = undefined;
  state.pendingReset = false;
  await active?.shutdown();
};
