import type { SdkHealthReporter, Transport } from "@sazabi/client-sdk-core";
import {
  isThenable,
  listKeysNow,
  type ReadResult,
  readKeyNow,
  removeKey,
  writeKey,
} from "./storage";
import type { StorageAdapter } from "./types";

/**
 * The outbox stores each batch under its own key, `sazabi.outbox.<id>` (a
 * JSON list of envelopes), and lists the ids under an index key. A crash
 * writes only its own batch and then the index, a few hundred bytes, instead
 * of rewriting every stored report: React Native kills the process within
 * milliseconds of the handler returning, and a promise-returning store
 * (AsyncStorage) never finished a rewrite of the whole list in that window.
 *
 * The two writes are issued back to back but land separately (AsyncStorage's
 * `multiSet` is one SQLite transaction on Android but one file per large
 * value plus a manifest on iOS, so no single call is atomic on both), and a
 * process seen dying between them on an Android device left a batch key no
 * index listed. The crash path stays two writes, as a dying process has no
 * time for more; the next launch reconciles instead: with an adapter that
 * lists its keys (`getAllKeys`), every `sazabi.outbox.<id>` key neither index
 * names is read as a stored batch and listed, so it is delivered and its key
 * removed like any other. The listing is read once per launch, issued just
 * before the index reads, before any capture installs.
 *
 * The ordering contract that makes an unlisted key mean exactly that: a
 * batch key is written before the index lists it, and removed before the
 * index stops listing it. So a listed id whose key reads as missing is a
 * delivery (or a drop) whose cleanup did not finish and is dropped, while a
 * key no index names can only be a crash whose index write never landed. A
 * key the store refuses to remove is overwritten with an empty list, which
 * reads as holding no report and goes on the next launch.
 */
const BATCH_KEY_PREFIX = "sazabi.outbox.";
export const OUTBOX_INDEX_KEY = "sazabi.outbox.index";
/**
 * Batches stashed by this launch before its read of the index came back.
 * They are listed under their own key so a crash right after `init()` never
 * overwrites a previous launch's index that has not been loaded yet; the
 * read merges them into the index and clears this key. A synchronous adapter
 * is read inside `init()`, so only a promise-returning one ever uses it.
 */
const UNMERGED_INDEX_KEY = "sazabi.outbox.index.unmerged";
/**
 * The format before per-batch keys: the whole outbox as one JSON list of
 * envelopes, plus the same list for batches stashed before the read. Read
 * and moved into batch keys, then removed; never written.
 */
const LEGACY_OUTBOX_KEY = "sazabi.outbox";
const LEGACY_UNMERGED_KEY = "sazabi.outbox.unmerged";
/**
 * The live queue as it stood when the app last left the foreground, as
 * `{ id, envelopes }`, so events not yet delivered survive the OS killing a
 * backgrounded app. Removed once the queue has been delivered; the next
 * launch moves what it finds into a batch keyed by its replay id.
 */
const QUEUE_KEY = "sazabi.outbox.queue";
/** Stamped on every record of a stashed batch; a re-sent copy carries the same value. */
export const OUTBOX_REPLAY_ID_KEY = "app.outbox.id";
const MAX_OUTBOX_ENVELOPES = 20;
/**
 * Hard cap on the stored outbox, in UTF-16 units (what a string store
 * counts): Android's AsyncStorage reads a row through a 2 MB cursor window,
 * and a crash report must never be the row that no longer loads.
 */
const MAX_OUTBOX_LENGTH = 524_288;

const batchKey = (id: string): string => `${BATCH_KEY_PREFIX}${id}`;

/**
 * What a batch id looks like: the 16 hex digits of a replay id, or the two
 * fixed ids of the legacy move. Only a key of that shape is read back as an
 * unlisted batch, so the index, the unmerged index, the saved queue, and any
 * key a later version adds under the prefix are never read as a corrupt
 * batch and removed.
 */
const BATCH_ID = /^(?:[0-9a-f]{16}|legacy|legacy-unmerged)$/;

/** The ids of the batch keys among `keys` that `listed` does not name. */
const unlistedBatchIds = (
  keys: readonly string[] | undefined,
  listed: ReadonlySet<string>,
): string[] =>
  (keys ?? [])
    .filter((key) => key.startsWith(BATCH_KEY_PREFIX))
    .map((key) => key.slice(BATCH_KEY_PREFIX.length))
    .filter((id) => BATCH_ID.test(id) && !listed.has(id));

/** One stored batch; `envelopes` is unset when its key could not be read. */
interface Batch {
  id: string;
  envelopes?: string[];
}

/**
 * Everything the keys should hold right now: what earlier launches left plus
 * what this launch stashed, minus what the intake has accepted. Every
 * delivery, old or new, reconciles against this one state and persists all
 * of it, so a launch's upload that finishes after a fresh crash can neither
 * erase the new batch nor resurrect its own accepted envelopes. The state is
 * the adapter's, not the SDK instance's: a delivery that outlives a
 * `shutdown()` keeps reconciling against the same state, and a later
 * `init()` on the same adapter starts from it rather than from an empty one.
 */
interface OutboxState {
  batches: Batch[];
  /** Stashed before `loaded`; listed under `UNMERGED_INDEX_KEY` until then. */
  unmerged: Batch[];
  /**
   * Whether the index has been read and merged. A read that failed leaves
   * this false for the rest of the process, so the index is never
   * overwritten with a list that is missing what it held.
   */
  loaded: boolean;
  /**
   * Whether `UNMERGED_INDEX_KEY` has been read: unset while the first read
   * is pending, `false` once a read failed and none has succeeded. A failed
   * read leaves a crash this launch knows nothing about possibly listed in
   * the key, so it is never written or removed then (the next launch reads
   * it again); a pending one still takes this launch's stash, as the dying
   * process has nowhere else to put it.
   */
  unmergedRead?: boolean;
  /** Whether the previous launch's saved queue has been read and moved. */
  queueRead?: boolean;
  /**
   * The transport whose queue `QUEUE_KEY` holds. Only that transport's
   * delivery clears the key: an upload of an instance already shut down
   * must not remove the copy a later `init()` on the same adapter saved.
   */
  queueSaved?: Transport;
  /** The read of the stored keys, started once per adapter per process. */
  loading?: Promise<void>;
  /** Envelopes with an upload outstanding: a second delivery never posts them again. */
  inFlight: Set<string>;
  warn?: (message: string) => void;
  /**
   * The running instance's health reporter (`watchOutbox`): told once how
   * many stored reports a load or a stash discarded (`outbox_discarded`,
   * with what a saved queue left out as `outbox_unsaved`) and when the
   * store refused a write (`outbox_persist_failed`). Unset after
   * `shutdown()`, so a delivery that outlives the instance is quiet.
   */
  report?: SdkHealthReporter;
  /** Stored envelopes known lost since the last report: by the caps, or as corrupt. */
  discarded: number;
  /**
   * Envelopes a replayed saved queue had left out at the caps. Their live
   * upload may or may not have finished before the kill, so they are
   * possible losses, never counted as discarded.
   */
  unsaved: number;
}

const stateByAdapter = new WeakMap<StorageAdapter, OutboxState>();

const stateFor = (adapter: StorageAdapter): OutboxState => {
  const state = stateByAdapter.get(adapter);
  if (state) return state;
  const fresh: OutboxState = {
    batches: [],
    unmerged: [],
    loaded: false,
    inFlight: new Set(),
    discarded: 0,
    unsaved: 0,
  };
  stateByAdapter.set(adapter, fresh);
  return fresh;
};

/**
 * Route the outbox's health reports to the running instance. Set before
 * `loadOutbox`, so what the first read discards is reported on this launch.
 */
export const watchOutbox = (
  adapter: StorageAdapter,
  report: SdkHealthReporter,
): void => {
  stateFor(adapter).report = report;
};

/** The instance is gone: nothing it would have reported is reported. */
export const unwatchOutbox = (
  adapter: StorageAdapter,
  report: SdkHealthReporter,
): void => {
  const state = stateFor(adapter);
  if (state.report === report) state.report = undefined;
};

/**
 * Tell the instance how many stored reports were discarded since it last
 * heard, and how many a saved queue had left out (possible losses, apart).
 */
const reportDiscarded = (state: OutboxState): void => {
  if (state.discarded === 0 && state.unsaved === 0) return;
  const { discarded, unsaved } = state;
  state.discarded = 0;
  state.unsaved = 0;
  state.report?.({
    diagnostic: "outbox_discarded",
    attributes: {
      "app.sdk.outbox_discarded": discarded,
      "app.sdk.outbox_unsaved": unsaved,
    },
  });
};

/**
 * A write the store refused: the instance that issued it hears of the first
 * one. The reporter is taken when the write starts, so a write still pending
 * through `shutdown()` and a later `init()` on the same adapter reports to
 * no one, never to the new instance (whose one report would be spent on a
 * session it did not run).
 */
const reportRefused = (
  state: OutboxState,
  accepted: boolean | Promise<boolean>,
): void => {
  const report = state.report;
  if (!report) return;
  void after(accepted, (ok) => {
    if (!ok && state.report === report) {
      report({ diagnostic: "outbox_persist_failed" });
    }
  });
};

/** Run `next` on a value now, or once it resolves. */
const after = <T, U>(
  value: T | Promise<T>,
  next: (resolved: T) => U | Promise<U>,
): U | Promise<U> =>
  isThenable(value)
    ? Promise.resolve(value as Promise<T>).then(next)
    : next(value as T);

/** Every value, synchronously when every one is synchronous. */
const all = <T>(values: Array<T | Promise<T>>): T[] | Promise<T[]> =>
  values.some(isThenable) ? Promise.all(values) : (values as T[]);

/** Read keys, synchronously when every answer is synchronous. */
const readKeys = (
  adapter: StorageAdapter,
  keys: string[],
): ReadResult[] | Promise<ReadResult[]> =>
  all(keys.map((key) => readKeyNow(adapter, key)));

const writeJson = (
  adapter: StorageAdapter,
  key: string,
  list: unknown[],
): boolean | Promise<boolean> =>
  list.length === 0
    ? removeKey(adapter, key)
    : writeKey(adapter, key, JSON.stringify(list));

const ids = (batches: Batch[]): string[] => batches.map((batch) => batch.id);

/**
 * Each batch id once, first place kept: a launch that wrote the index and
 * died before removing the unmerged index leaves an id in both, and trimming
 * a list that counts it twice would drop reports that fit the caps.
 */
const uniqueBatches = (batches: Batch[]): Batch[] => {
  const seen = new Set<string>();
  return batches.filter((batch) => {
    if (seen.has(batch.id)) return false;
    seen.add(batch.id);
    return true;
  });
};

/**
 * Before the index is loaded only the unmerged index is written, so the
 * previous launch's index stays where it is; after, the merged list is the
 * index and the unmerged key goes, but only once the index write was
 * accepted and only if the key was read. An unmerged key whose read failed
 * is left alone, written or removed: its contents are unknown. Answers
 * `true` synchronously when a synchronous adapter took the write.
 */
const persist = (adapter: StorageAdapter): boolean | Promise<boolean> => {
  const state = stateFor(adapter);
  if (!state.loaded) {
    return (
      state.unmergedRead !== false &&
      writeJson(adapter, UNMERGED_INDEX_KEY, ids(state.unmerged))
    );
  }
  return after(
    writeJson(adapter, OUTBOX_INDEX_KEY, ids(state.batches)),
    (accepted) =>
      accepted && state.unmergedRead
        ? after(removeKey(adapter, UNMERGED_INDEX_KEY), () => accepted)
        : accepted,
  );
};

/** The newest envelopes within both caps, at least one. */
const capEnvelopes = (envelopes: string[]): string[] => {
  let length = 0;
  let keep = 0;
  for (let index = envelopes.length - 1; index >= 0; index -= 1) {
    length += (envelopes[index] as string).length;
    if (
      keep === MAX_OUTBOX_ENVELOPES ||
      (length > MAX_OUTBOX_LENGTH && keep > 0)
    )
      break;
    keep += 1;
  }
  return envelopes.slice(envelopes.length - keep);
};

/** Drop the oldest batches past either cap, keeping the newest; returns them, counted as discarded. */
const trim = (state: OutboxState, batches: Batch[]): Batch[] => {
  let count = 0;
  let length = 0;
  for (let index = batches.length - 1; index >= 0; index -= 1) {
    const envelopes = batches[index]?.envelopes ?? [];
    count += envelopes.length;
    for (const body of envelopes) length += body.length;
    if (
      index < batches.length - 1 &&
      (count > MAX_OUTBOX_ENVELOPES || length > MAX_OUTBOX_LENGTH)
    ) {
      const dropped = batches.splice(0, index + 1);
      for (const batch of dropped) {
        state.discarded += batch.envelopes?.length ?? 0;
      }
      return dropped;
    }
  }
  return [];
};

const parseJson = (raw: string): unknown => {
  try {
    return JSON.parse(raw);
  } catch {
    return undefined;
  }
};

/** The strings in a parsed value; anything but a list (a corrupt value, another version's shape) is empty. */
const stringsOf = (parsed: unknown): string[] =>
  Array.isArray(parsed)
    ? parsed.filter((entry): entry is string => typeof entry === "string")
    : [];

/** A stored list of ids. */
const parseList = (raw: string | null | undefined): string[] =>
  stringsOf(raw ? parseJson(raw) : undefined);

/**
 * Stored envelopes, validated on read: a value that is not a JSON list, and
 * every entry that is not a JSON object, is discarded rather than posted,
 * with one warning. `discarded` (how many entries, or one for a value that
 * is no list at all) tells the caller the key holds something it should
 * not, so the key is rewritten or removed and the warning does not come
 * back on the next launch; the count is reported as `outbox_discarded`.
 */
const parseEnvelopes = (
  state: OutboxState,
  raw: string | null | undefined,
): { envelopes: string[]; discarded: number } => {
  const parsed = raw ? parseJson(raw) : undefined;
  const envelopes = stringsOf(parsed).filter((body) => {
    const envelope = parseJson(body);
    return typeof envelope === "object" && envelope !== null;
  });
  const discarded = !raw
    ? 0
    : Array.isArray(parsed)
      ? parsed.length - envelopes.length
      : 1;
  state.discarded += discarded;
  if (discarded) {
    // Once per process: the same value is read again by every init().
    state.warn?.("discarded a stored crash report that is not valid JSON.");
    state.warn = undefined;
  }
  return { envelopes, discarded };
};

const merge = (
  adapter: StorageAdapter,
  state: OutboxState,
  [index, unmergedIndex, legacy, legacyUnmerged, queue]: ReadResult[],
  batchReads: Map<string, ReadResult>,
  unlisted: string[],
): void => {
  if (unmergedIndex) state.unmergedRead = true;
  else if (state.unmergedRead === undefined) state.unmergedRead = false;
  // An id whose key reads as missing was delivered (its key removed before
  // the index was rewritten) or never written: gone. One whose key holds no
  // valid report is gone too (its key is removed once the index no longer
  // lists it), and one holding some is rewritten with just those, the batch
  // before the index as always: otherwise the corrupt value would be read,
  // warned about, and kept on every launch.
  const corrupt = new Set<string>();
  const readBatches = new Map<string, Batch[]>();
  const batchesOf = (listed: string[]): Batch[] =>
    listed.flatMap((id) => {
      // An id listed in both indexes is read, judged, and rewritten once.
      const seen = readBatches.get(id);
      if (seen) return seen;
      const read = batchReads.get(id);
      let batches: Batch[];
      if (!read) batches = [{ id }];
      else if (read.value === null) batches = [];
      else {
        const { envelopes, discarded } = parseEnvelopes(state, read.value);
        if (envelopes.length === 0) {
          corrupt.add(id);
          batches = [];
        } else {
          if (discarded) void writeJson(adapter, batchKey(id), envelopes);
          batches = [{ id, envelopes }];
        }
      }
      readBatches.set(id, batches);
      return batches;
    });
  const stored = batchesOf(parseList(index?.value));
  const held = batchesOf(parseList(unmergedIndex?.value));
  // A batch key no index names: a crash whose index write never landed.
  // Read and judged like a listed one, then listed below, so it is
  // delivered and its key removed like any other. One this launch stashed
  // itself is already in the state and not read back. Several come in the
  // store's own order, which says nothing about their age, so a trim at
  // the caps may prefer an older one; a replay id carries no clock.
  const own = new Set(ids([...state.batches, ...state.unmerged]));
  const found = batchesOf(unlisted.filter((id) => !own.has(id)));
  if (!index && state.unmergedRead === false) {
    // Nowhere safe to list anything: leave every key for the next launch,
    // which reads and counts them again; nothing was discarded here.
    state.discarded = 0;
    state.unsaved = 0;
    return;
  }
  // The old single-list format and the previous launch's saved queue move
  // into batch keys, each written before the index lists it; an old key
  // goes only once both its batch write and the index write were accepted
  // (a store near its quota may refuse the batch and take the small index),
  // and otherwise stays for the next launch to move again. A batch id
  // already listed (a move whose cleanup did not finish) is not added twice.
  const known = new Set(
    ids([...stored, ...held, ...found, ...state.batches, ...state.unmerged]),
  );
  const moved: Batch[] = [];
  const move = (
    id: string | undefined,
    envelopes: string[],
  ): boolean | Promise<boolean> => {
    if (!id || envelopes.length === 0 || known.has(id)) return true;
    known.add(id);
    // The key this move writes replaces a corrupt one of the same id (a
    // legacy move whose cleanup did not finish): it must not be removed.
    corrupt.delete(id);
    moved.push({ id, envelopes });
    return writeJson(adapter, batchKey(id), envelopes);
  };
  const sources: Array<[string, boolean | Promise<boolean>]> = [];
  for (const [result, id, key] of [
    [legacy, "legacy", LEGACY_OUTBOX_KEY],
    [legacyUnmerged, "legacy-unmerged", LEGACY_UNMERGED_KEY],
  ] as const) {
    if (!result?.value) continue;
    sources.push([
      key,
      move(id, parseEnvelopes(state, result.value).envelopes),
    ]);
  }
  const saved = queue?.value
    ? (parseJson(queue.value) as {
        id?: unknown;
        envelopes?: unknown;
        discarded?: unknown;
      } | null)
    : undefined;
  // Rows the save left out at the caps: the copy is being replayed, so the
  // app was killed before the live queue settled, but the transport posts
  // the oldest first and these may have been delivered before the kill.
  // Possible losses, reported apart from what is known gone.
  if (typeof saved?.discarded === "number" && saved.discarded > 0) {
    state.unsaved += Math.floor(saved.discarded);
  }
  const queueMoved = move(
    typeof saved?.id === "string" ? saved.id : undefined,
    parseEnvelopes(state, JSON.stringify(saved?.envelopes ?? [])).envelopes,
  );
  let dropped: Batch[];
  if (index) {
    // A crash during the read may already have stashed a batch; everything
    // stored joins it rather than replacing it.
    state.batches = uniqueBatches([
      ...stored,
      ...held,
      ...found,
      ...moved,
      ...state.unmerged,
    ]);
    state.unmerged = [];
    state.loaded = true;
    dropped = trim(state, state.batches);
  } else {
    // `found` is empty here: nothing is unlisted while the index is unread.
    state.unmerged = uniqueBatches([...held, ...moved, ...state.unmerged]);
    dropped = trim(state, state.unmerged);
  }
  // What this read threw away, on the launch that found it: the crash that
  // overfilled the store could not say so itself.
  reportDiscarded(state);
  void after(persist(adapter), (accepted) => {
    for (const id of ids(dropped)) void removeKey(adapter, batchKey(id));
    if (!accepted) return;
    for (const id of corrupt) void removeKey(adapter, batchKey(id));
    return after(
      all([queueMoved, ...sources.map(([, written]) => written)]),
      ([queueWritten, ...written]) => {
        for (const [at, [key]] of sources.entries()) {
          if (written[at]) void removeKey(adapter, key);
        }
        // A saved queue that could not be moved keeps its key, and saves
        // stay off for the launch so they never overwrite it.
        if (!queue || !queueWritten) return;
        // Saves of this launch's queue start only once the previous
        // launch's copy is gone, so its removal can never delete the new one.
        return after(queue.value ? removeKey(adapter, QUEUE_KEY) : true, () => {
          state.queueRead = true;
        });
      },
    );
  });
};

/**
 * Read the stored outbox once per adapter. Started by `init()` before any
 * capture installs: a synchronous adapter is loaded before this returns, so
 * a crash at any later point merges into the stored report instead of
 * writing beside it.
 */
export const loadOutbox = (
  adapter: StorageAdapter,
  warn?: (message: string) => void,
): Promise<void> => {
  const state = stateFor(adapter);
  if (state.loading) return state.loading;
  state.warn ??= warn;
  // The listing is issued before the index reads, so on a store that runs
  // calls in order (AsyncStorage) it is taken no later than the indexes it
  // is compared against: a batch whose index write lands between the two
  // is listed, and a key the listing misses is at worst found next launch.
  const keysRead = listKeysNow(adapter);
  const loaded = after(
    readKeys(adapter, [
      OUTBOX_INDEX_KEY,
      UNMERGED_INDEX_KEY,
      LEGACY_OUTBOX_KEY,
      LEGACY_UNMERGED_KEY,
      QUEUE_KEY,
    ]),
    (indexes) =>
      after(keysRead, (keys) => {
        const listed = [
          ...new Set([
            ...parseList(indexes[0]?.value),
            ...parseList(indexes[1]?.value),
          ]),
        ];
        // Only with both indexes read: an index that failed to read may
        // list any key, so nothing is unlisted until a launch reads it.
        const unlisted =
          indexes[0] && indexes[1]
            ? unlistedBatchIds(keys, new Set(listed))
            : [];
        const toRead = [...listed, ...unlisted];
        return after(readKeys(adapter, toRead.map(batchKey)), (reads) => {
          merge(
            adapter,
            state,
            indexes,
            new Map(toRead.map((id, index) => [id, reads[index]])),
            unlisted,
          );
        });
      }),
  );
  if (!isThenable(loaded)) {
    // A failed read is tried again by the next init() in this process.
    if (state.loaded) state.loading = Promise.resolve();
    return Promise.resolve();
  }
  const loading = loaded.then(() => {
    if (!state.loaded) state.loading = undefined;
  });
  state.loading = loading;
  return loading;
};

/**
 * Post envelopes and drop from the state only the settled ones, accepted or
 * refused for good (a 4xx other than 408 and 429, which the transport warns
 * about once): an offline launch, a 429, or a 5xx keeps the rest for the
 * next launch instead of deleting the only copy of a crash, and a report the
 * intake will never take is not posted on every launch forever.
 */
const deliver = async (
  adapter: StorageAdapter,
  transport: Transport,
  envelopes: string[],
): Promise<void> => {
  const state = stateFor(adapter);
  const fresh = envelopes.filter((body) => !state.inFlight.has(body));
  if (fresh.length === 0) return;
  for (const body of fresh) state.inFlight.add(body);
  let settled: boolean[];
  try {
    settled = await Promise.all(
      fresh.map((body) => transport.sendEnvelope(body)),
    );
  } finally {
    for (const body of fresh) state.inFlight.delete(body);
  }
  const delivered = new Set(fresh.filter((_, index) => settled[index]));
  if (delivered.size === 0) return;
  const emptied: Array<[Batch[], Batch]> = [];
  for (const list of [state.batches, state.unmerged]) {
    for (const batch of list) {
      const left = batch.envelopes?.filter((body) => !delivered.has(body));
      if (!left || left.length === batch.envelopes?.length) continue;
      batch.envelopes = left;
      if (left.length > 0) void writeJson(adapter, batchKey(batch.id), left);
      else emptied.push([list, batch]);
    }
  }
  // A settled batch's key goes before the index stops naming it (the
  // ordering contract in the file comment): a process dying in between
  // leaves a listed id whose key is missing, which the next launch drops,
  // never an unlisted key it would read as a lost crash and post again. A
  // key the store refuses to remove is left holding no report instead, and
  // one it refuses to touch at all stays listed with its contents, so the
  // next launch posts it again under the same replay id rather than losing
  // track of a key it cannot clear.
  const cleared = await all(
    emptied.map(([, batch]) =>
      after(
        removeKey(adapter, batchKey(batch.id)),
        (removed) => removed || writeKey(adapter, batchKey(batch.id), "[]"),
      ),
    ),
  );
  emptied.forEach(([list, batch], at) => {
    const index = list.indexOf(batch);
    if (cleared[at] && index >= 0) list.splice(index, 1);
  });
  await persist(adapter);
};

/**
 * The crash outbox replaces the browser's keepalive flush. A fatal JavaScript
 * error terminates the process shortly after the global handler returns, so
 * the pending queue (the error row included) is encoded into standalone
 * envelopes stamped with one replay id and written to storage: the batch's
 * own key first, then the index that lists it.
 *
 * Nothing the dying process sends can be cleared afterwards: an upload the
 * intake accepted just before the process died would be posted again by the
 * next launch. So when a synchronous adapter took both writes (`true`),
 * nothing is sent here; the caller delivers the outbox once the process has
 * proved it survived, and otherwise the next `init()` does. A
 * promise-returning adapter may never finish the writes, so its batch is
 * also sent at once, and a copy the next launch re-sends carries the same
 * replay id. The saved queue goes once both writes were accepted (every row
 * it held is in this batch), never before: a store that refuses the batch
 * near its limit must not cost the only copy of those rows.
 */
export const stashOutbox = (
  adapter: StorageAdapter,
  transport: Transport,
  replayId: string,
): boolean => {
  const drained = transport.drainEnvelopes({
    [OUTBOX_REPLAY_ID_KEY]: replayId,
  });
  const envelopes = capEnvelopes(drained);
  if (envelopes.length === 0) return true;
  const state = stateFor(adapter);
  state.discarded += drained.length - envelopes.length;
  const list = state.loaded ? state.batches : state.unmerged;
  list.push({ id: replayId, envelopes });
  const dropped = trim(state, list);
  const written = writeJson(adapter, batchKey(replayId), envelopes);
  const indexed = persist(adapter);
  const durable = indexed === true && written === true;
  for (const id of ids(dropped)) void removeKey(adapter, batchKey(id));
  // Heard only if the process survives the crash (a development build, a
  // handler that does not terminate); a dying process has no time to say so.
  reportDiscarded(state);
  reportRefused(state, written);
  // `persist` skips the index write (answering `false`) while the unmerged
  // index is unreadable; only a write the store was given can be refused.
  if (state.loaded || state.unmergedRead !== false) {
    reportRefused(state, indexed);
  }
  if (state.queueSaved === transport) {
    // No delivery clears the saved queue from here on: it goes only once
    // both writes are on disk, and a refused write leaves it for the next
    // launch to replay. A newer save in the meantime is never removed.
    state.queueSaved = undefined;
    void after(all([written, indexed]), (accepted) => {
      if (accepted.every(Boolean) && state.queueSaved === undefined) {
        void removeKey(adapter, QUEUE_KEY);
      }
    });
  }
  if (!durable) void deliver(adapter, transport, envelopes);
  return durable;
};

/** Post everything the outbox holds once the stored keys have been read. */
export const deliverOutbox = async (
  adapter: StorageAdapter,
  transport: Transport,
): Promise<void> => {
  await loadOutbox(adapter);
  const state = stateFor(adapter);
  await deliver(adapter, transport, [
    ...new Set(
      [...state.batches, ...state.unmerged].flatMap(
        (batch) => batch.envelopes ?? [],
      ),
    ),
  ]);
};

/**
 * Save the live queue, within the outbox caps, as the app leaves the
 * foreground: the OS may kill a backgrounded app without another callback,
 * and an offline queue would die with it. The queued records are stamped
 * with the replay id, so the live upload and the copy a later launch sends
 * share it. Not before the previous launch's saved queue has been read.
 */
export const saveQueue = (
  adapter: StorageAdapter,
  transport: Transport,
  replayId: string,
): void => {
  const state = stateFor(adapter);
  if (!state.queueRead) return;
  const snapshot = transport.snapshotEnvelopes({
    [OUTBOX_REPLAY_ID_KEY]: replayId,
  });
  const envelopes = capEnvelopes(snapshot);
  state.queueSaved = envelopes.length > 0 ? transport : undefined;
  if (state.queueSaved) {
    // What the caps left out is still in the live queue; the copy records
    // the count, and the launch that replays the copy reports it as
    // `outbox_unsaved` (the live upload may have delivered it).
    const discarded = snapshot.length - envelopes.length;
    reportRefused(
      state,
      writeKey(
        adapter,
        QUEUE_KEY,
        JSON.stringify(
          discarded > 0
            ? { id: replayId, envelopes, discarded }
            : { id: replayId, envelopes },
        ),
      ),
    );
  } else {
    void removeKey(adapter, QUEUE_KEY);
  }
};

/**
 * `transport`'s live queue was delivered (or stashed by a crash): its saved
 * copy goes, unless the key now holds another transport's queue.
 */
export const clearQueue = (
  adapter: StorageAdapter,
  transport: Transport,
): void => {
  const state = stateFor(adapter);
  if (state.queueSaved !== transport) return;
  state.queueSaved = undefined;
  void removeKey(adapter, QUEUE_KEY);
};
