import { type RandomBytes, toHex } from "./random";

export interface RequestTraceContext {
  /** Headers to inject (`traceparent`, and `tracestate` when present). */
  headers: Record<string, string>;
  traceId: string;
  spanId: string;
}

export interface TraceContextManager {
  /** Trace context for one outgoing request, minted at request time. */
  forRequest(): RequestTraceContext;
}

/** The subset of an OTel SpanContext this module consumes. */
export interface HostSpanContext {
  traceId: string;
  spanId: string;
  traceFlags: number;
  traceState?: { serialize(): string };
}

const SAMPLED_FLAG = 0x1;
const TRACE_ID_PATTERN = /^[0-9a-f]{32}$/;
const SPAN_ID_PATTERN = /^[0-9a-f]{16}$/;
const ALL_ZERO_TRACE_ID = "0".repeat(32);
const ALL_ZERO_SPAN_ID = "0".repeat(16);

const randomHexId = (randomBytes: RandomBytes, byteLength: number): string => {
  let bytes: Uint8Array;
  do {
    bytes = randomBytes(byteLength);
  } while (bytes.every((b) => b === 0)); // all-zero ids are invalid per W3C spec
  return toHex(bytes);
};

const isValidHostSpanContext = (
  candidate: unknown,
): candidate is HostSpanContext => {
  if (typeof candidate !== "object" || candidate === null) return false;
  const { traceId, spanId, traceFlags } = candidate as HostSpanContext;
  return (
    typeof traceId === "string" &&
    TRACE_ID_PATTERN.test(traceId) &&
    traceId !== ALL_ZERO_TRACE_ID &&
    typeof spanId === "string" &&
    SPAN_ID_PATTERN.test(spanId) &&
    spanId !== ALL_ZERO_SPAN_ID &&
    typeof traceFlags === "number"
  );
};

// ------------------------------------------------- host OTel interop --------
// Dependency-free read of the host app's active span, through the
// @opentelemetry/api package's own cross-copy compatibility contract: every
// api copy interoperates via the global delegate registered at
// Symbol.for("opentelemetry.js.api.1"), and context keys are Symbol.for(...)
// strings. That registry IS the mechanism by which independent api copies
// find each other, which is what makes it load-bearing rather than private.
// An integration test against the real api package (devDependency of the
// browser SDK) pins the contract; any shape drift degrades here to "no
// active span" and we mint our own roots instead.

const OTEL_GLOBAL_KEY = Symbol.for("opentelemetry.js.api.1");
const OTEL_SPAN_CONTEXT_KEY = Symbol.for("OpenTelemetry Context Key SPAN");

interface OtelGlobalShape {
  context?: {
    active?: () => { getValue?: (key: symbol) => unknown } | undefined;
  };
}

export const readHostSpanContext = (): HostSpanContext | undefined => {
  try {
    const otelApi = (globalThis as Record<symbol, unknown>)[OTEL_GLOBAL_KEY] as
      | OtelGlobalShape
      | undefined;
    const activeContext = otelApi?.context?.active?.();
    const span = activeContext?.getValue?.(OTEL_SPAN_CONTEXT_KEY) as
      | { spanContext?: () => unknown }
      | undefined;
    const candidate = span?.spanContext?.();
    return isValidHostSpanContext(candidate) ? candidate : undefined;
  } catch {
    return undefined;
  }
};

const formatTraceparent = (spanContext: HostSpanContext): string => {
  const flags = (spanContext.traceFlags & 0xff).toString(16).padStart(2, "0");
  return `00-${spanContext.traceId}-${spanContext.spanId}-${flags}`;
};

const readTraceState = (spanContext: HostSpanContext): string | undefined => {
  try {
    const serialized = spanContext.traceState?.serialize();
    return serialized || undefined;
  } catch {
    return undefined;
  }
};

/**
 * W3C trace context for outgoing requests: hand-rolled header formatting
 * (equivalence-tested against OTel's W3CTraceContextPropagator), zero
 * runtime dependencies. If the host app runs its own OTel and has an active
 * span, that span's context (including its flags and tracestate) is reused
 * so we join the customer's trace instead of forking a new one; otherwise a
 * fresh root is minted with the sampled flag defaulting to off (`-00`).
 */
export const createTraceContextManager = (options: {
  sampledFlag: boolean;
  randomBytes: RandomBytes;
}): TraceContextManager => {
  const mintRootSpanContext = (): HostSpanContext => ({
    traceId: randomHexId(options.randomBytes, 16),
    spanId: randomHexId(options.randomBytes, 8),
    traceFlags: options.sampledFlag ? SAMPLED_FLAG : 0,
  });

  return {
    forRequest() {
      const spanContext = readHostSpanContext() ?? mintRootSpanContext();
      const headers: Record<string, string> = {
        traceparent: formatTraceparent(spanContext),
      };
      const traceState = readTraceState(spanContext);
      if (traceState) {
        headers.tracestate = traceState;
      }
      return {
        headers,
        traceId: spanContext.traceId,
        spanId: spanContext.spanId,
      };
    },
  };
};
