import { newPrefixedId, type RandomBytes } from "./random";

const SESSION_STORAGE_KEY = "sazabi.session";
const WINDOW_STORAGE_KEY = "sazabi.windowId";
const DISTINCT_STORAGE_KEY = "sazabi.distinctId";

const SESSION_IDLE_MS = 30 * 60 * 1000;
const SESSION_MAX_MS = 24 * 60 * 60 * 1000;
/**
 * How far the wall clock may run behind the stored activity time before the
 * stored session no longer counts. A clock set back by hours would otherwise
 * keep a session alive past its idle and age limits, since both are measured
 * as `now` minus a time that now lies in the future.
 */
const CLOCK_SKEW_MS = 60 * 1000;
/** Throttle activity writes; click bursts must not spam storage. */
const ACTIVITY_PERSIST_INTERVAL_MS = 5_000;

interface StoredSession {
  id: string;
  startedAt: number;
  lastActivityAt: number;
}

/**
 * Synchronous key-value access the session machine reads through on every
 * call. A browser binding backs it with `localStorage` (so sibling tabs
 * converge) and `sessionStorage`; a mobile binding backs it with an
 * in-memory mirror hydrated from its storage adapter and written through.
 */
export interface SessionStore {
  get(key: string): string | null;
  set(key: string, value: string): void;
  remove(key: string): void;
}

/** A store that lives for the process only: the fallback on every host. */
export const createMemoryStore = (): SessionStore => {
  const memory = new Map<string, string>();
  return {
    get: (key) => memory.get(key) ?? null,
    set: (key, value) => {
      memory.set(key, value);
    },
    remove: (key) => {
      memory.delete(key);
    },
  };
};

export interface SessionManager {
  getSessionId(): string;
  getWindowId(): string;
  getDistinctId(): string | undefined;
  /**
   * Set the client-asserted identity. Switching from one identity directly
   * to a different one rotates the session and window ids so two users on a
   * shared device never thread into one timeline.
   */
  setDistinctId(distinctId: string): void;
  /** Logout: clear identity and rotate both session and window ids. */
  reset(): void;
  /** Record user activity; may rotate the session on idle/max-age expiry. */
  touch(): void;
}

export interface SessionManagerOptions {
  /** Visit-scoped state: session id and identity. */
  store: SessionStore;
  /** Window-scoped state: one browser tab, or one app launch. */
  windowStore: SessionStore;
  randomBytes: RandomBytes;
}

const parseStoredSession = (raw: string | null): StoredSession | undefined => {
  if (!raw) return undefined;
  try {
    const parsed: unknown = JSON.parse(raw);
    if (
      typeof parsed === "object" &&
      parsed !== null &&
      typeof (parsed as StoredSession).id === "string" &&
      typeof (parsed as StoredSession).startedAt === "number" &&
      typeof (parsed as StoredSession).lastActivityAt === "number"
    ) {
      return parsed as StoredSession;
    }
  } catch {
    // Corrupt value: treat as absent and rotate.
  }
  return undefined;
};

/**
 * Session identity. `session.id` is the visit (last-writer-wins on rotation
 * races between windows; a split session is cosmetic, not data loss).
 * `session.window_id` is this window. `session.distinct_id` is read through
 * the store so identify/reset in one window is visible to siblings on their
 * next event.
 */
export const createSessionManager = (
  options: SessionManagerOptions,
): SessionManager => {
  const { store, windowStore, randomBytes } = options;

  let lastPersistedActivity = 0;

  const readOrRotate = (): StoredSession => {
    const now = Date.now();
    const stored = parseStoredSession(store.get(SESSION_STORAGE_KEY));

    if (
      stored &&
      now - stored.lastActivityAt <= SESSION_IDLE_MS &&
      now - stored.lastActivityAt >= -CLOCK_SKEW_MS &&
      now - stored.startedAt <= SESSION_MAX_MS
    ) {
      return stored;
    }

    const fresh: StoredSession = {
      id: newPrefixedId(randomBytes, "sess"),
      startedAt: now,
      lastActivityAt: now,
    };
    store.set(SESSION_STORAGE_KEY, JSON.stringify(fresh));
    lastPersistedActivity = now;
    return fresh;
  };

  let windowId = windowStore.get(WINDOW_STORAGE_KEY);
  if (!windowId) {
    windowId = newPrefixedId(randomBytes, "win");
    windowStore.set(WINDOW_STORAGE_KEY, windowId);
  }

  const rotate = (): void => {
    const now = Date.now();
    store.set(
      SESSION_STORAGE_KEY,
      JSON.stringify({
        id: newPrefixedId(randomBytes, "sess"),
        startedAt: now,
        lastActivityAt: now,
      }),
    );
    lastPersistedActivity = now;
    windowId = newPrefixedId(randomBytes, "win");
    windowStore.set(WINDOW_STORAGE_KEY, windowId);
  };

  return {
    getSessionId() {
      return readOrRotate().id;
    },
    getWindowId() {
      return windowId as string;
    },
    getDistinctId() {
      return store.get(DISTINCT_STORAGE_KEY) ?? undefined;
    },
    setDistinctId(id: string) {
      const current = store.get(DISTINCT_STORAGE_KEY) ?? undefined;
      if (current !== undefined && current !== id) {
        // Identity switch without reset(): defensive rotation so the new
        // user's events never join the previous user's session.
        rotate();
      }
      store.set(DISTINCT_STORAGE_KEY, id);
    },
    reset() {
      store.remove(DISTINCT_STORAGE_KEY);
      rotate();
    },
    touch() {
      const now = Date.now();
      const current = readOrRotate();
      if (now - lastPersistedActivity >= ACTIVITY_PERSIST_INTERVAL_MS) {
        store.set(
          SESSION_STORAGE_KEY,
          JSON.stringify({ ...current, lastActivityAt: now }),
        );
        lastPersistedActivity = now;
      }
    },
  };
};
