import {
  type ClientEvent,
  truncateValue,
  withoutConsoleCapture,
} from "@sazabi/client-sdk-core";
import { isDevHost } from "./host";
import { state } from "./process-state";
import type { RejectionTracker } from "./types";
import { SDK_CONSOLE_PREFIX } from "./version";

type GlobalHandler = (error: unknown, isFatal?: boolean) => void;

interface ErrorUtilsLike {
  getGlobalHandler?(): GlobalHandler | undefined;
  setGlobalHandler?(handler: GlobalHandler): void;
}

interface HermesInternalLike {
  enablePromiseRejectionTracker?(options: RejectionTracker): void;
}

const hermes = (): HermesInternalLike | undefined =>
  (globalThis as { HermesInternal?: HermesInternalLike }).HermesInternal;

/** Call a tracker callback without letting its throw reach Hermes or skip the next one. */
const notify = (call: () => void): void => {
  try {
    call();
  } catch {
    // Never throw into Hermes.
  }
};

export interface ErrorCaptureOptions {
  emit(event: ClientEvent): void;
  /**
   * Receives the fatal error's row instead of `emit`, before the previous
   * handler runs: the crash path must stamp that row with the transport held
   * so it cannot be flushed out of the queue before the outbox drains it.
   */
  onFatal(event: ClientEvent): void;
  unhandledRejections: boolean;
  /** The tracker the host says held the slot before `init()`; runs after ours. */
  previousRejectionTracker?: RejectionTracker;
}

export interface ErrorCaptureHandle {
  teardown(): void;
}

/**
 * Text for anything an app can throw, never throwing itself: a string as is,
 * an object as JSON (a cycle or a throwing `toJSON` falls back to its tag,
 * and a tag that throws too to a fixed string),
 * cut to the attribute limit before it is copied anywhere.
 */
const describe = (value: unknown): string => {
  try {
    const text =
      typeof value === "string"
        ? value
        : typeof value === "object" && value !== null
          ? (JSON.stringify(value) ?? String(value))
          : String(value);
    return truncateValue(text);
  } catch {
    // The tag can throw too (a throwing `Symbol.toStringTag` getter).
    try {
      return truncateValue(Object.prototype.toString.call(value));
    } catch {
      return "[unreadable thrown value]";
    }
  }
};

const errorEvent = (
  error: unknown,
  kind: "fatal" | "uncaught" | "unhandledrejection",
): ClientEvent => {
  // Read through guards: an Error may carry a throwing getter, a non-string
  // `name` or `stack`, or a 300 KB message.
  const fields = error instanceof Error ? error : undefined;
  const read = (key: "name" | "message" | "stack"): string | undefined => {
    try {
      const value: unknown = fields?.[key];
      return typeof value === "string" ? truncateValue(value) : undefined;
    } catch {
      return undefined;
    }
  };
  const exceptionType =
    read("name") ||
    (kind === "unhandledrejection" ? "UnhandledRejection" : "Error");
  const message = fields ? (read("message") ?? "") : describe(error);
  return {
    type: "error",
    body: truncateValue(`${exceptionType}: ${message}`, 512),
    severity: "ERROR",
    timeUnixMs: Date.now(),
    attributes: {
      "exception.type": exceptionType,
      "exception.message": message,
      "exception.stacktrace": read("stack") ?? "",
      "app.error.kind": kind,
    },
  };
};

/**
 * Where `<SazabiRoot>` reports a render or commit error it caught. React 19's
 * renderer hands an error no boundary caught straight to React Native's
 * `ExceptionsManager` (the renderer's `onUncaughtError`), never through
 * `ErrorUtils`, and the release app dies there. The root's boundary records
 * the error through the process-wide sink first (so a root from a second
 * copy of the module reaches the running instance), then rethrows it so
 * React Native's fatal path still runs unchanged.
 */
export const captureRenderError = (error: unknown): void => {
  try {
    state.renderErrorSink?.(error);
  } catch {
    // Capture failures must never surface to the host.
  }
};

const describeRejection = (rejection: unknown): string => {
  if (rejection instanceof Error) {
    // Hermes and V8 stacks open with the `Name: message` line.
    return rejection.stack || `${rejection.name}: ${rejection.message}`;
  }
  if (typeof rejection === "string") return rejection;
  try {
    return JSON.stringify(rejection) ?? String(rejection);
  } catch {
    return String(rejection);
  }
};

/**
 * React Native's own tracker only warns, and only in development
 * (`polyfillPromise.js` installs it under `__DEV__`, before any module of the
 * app can watch the slot). With no other tracker seen before ours, the chain
 * is its behavior, relayed: the same warning, which LogBox shows, kept out of
 * the console mirror.
 */
const warnInDev = (message: () => string): void => {
  if (!isDevHost()) return;
  try {
    // Formatting runs inside the guard: a rejection may be cyclic, have no
    // prototype, or carry a throwing getter.
    const text = message();
    withoutConsoleCapture(() => console.warn(text));
  } catch {
    // Never throw into the host.
  }
};

/**
 * Uncaught errors route through React Native's global handler; a fatal one
 * terminates the app once the handler returns, which is why the crash outbox
 * runs inside it. The previous handler (React Native's red box in
 * development, a crash reporter's hook) always runs after ours. Render
 * errors reach the same fatal path from `<SazabiRoot>` (`captureRenderError`);
 * a crash reported more than once in one task is recorded once.
 *
 * Hermes exposes one promise-rejection tracker slot and no way to read it:
 * `HermesInternal` is frozen (its methods non-writable and non-configurable,
 * the object non-extensible) and the global that names it is non-writable
 * and non-configurable too (`lib/VM/JSLib/HermesInternal.cpp`,
 * `lib/VM/JSLib/GlobalObject.cpp`), so the installer cannot be wrapped from
 * JavaScript and whoever held the slot before `init()` is unknowable. The
 * host hands that tracker over as `errors.previousRejectionTracker` and ours
 * runs it after recording; `errors.unhandledRejections: false` leaves the
 * slot alone. Without either, a development build is told once per process.
 */
export const installErrorCapture = (
  options: ErrorCaptureOptions,
): ErrorCaptureHandle => {
  const errorUtils = (globalThis as { ErrorUtils?: ErrorUtilsLike }).ErrorUtils;
  const previous = errorUtils?.getGlobalHandler?.();
  // Cleared by teardown. The Hermes rejection slot cannot be handed back (its
  // previous occupant is unknowable) and a later patcher may keep our global
  // handler in its chain, so both callbacks go inert instead: after shutdown
  // nothing is built or emitted, and the session store is never touched.
  let active = true;
  // One fatal row per task: React retries a failed render once before giving
  // up (a component that throws `new Error()` hands the boundary a second
  // instance), and a React 18 renderer rethrows the same crash into
  // `ErrorUtils`, all before the task ends.
  let fatalRecordedThisTask = false;

  const recordFatal = (error: unknown): void => {
    if (!active || fatalRecordedThisTask) return;
    fatalRecordedThisTask = true;
    setTimeout(() => {
      fatalRecordedThisTask = false;
    }, 0);
    options.onFatal(errorEvent(error, "fatal"));
  };

  // `isFatal` is React Native's own flag, passed through as `app.error.kind`:
  // a development build reports an uncaught error as fatal even though the
  // red box keeps the app alive, and `ErrorUtils.reportError` as not fatal.
  const handler: GlobalHandler = (error, isFatal) => {
    const callPrevious = (): void => previous?.(error, isFatal);
    if (!active) {
      callPrevious();
      return;
    }
    try {
      if (isFatal) {
        recordFatal(error);
      } else {
        options.emit(errorEvent(error, "uncaught"));
      }
    } catch {
      // Capture failures must never surface to the host.
    }
    // React Native's handler feeds the error back into `console.error`; the
    // error row already holds it, so the console mirror skips that line.
    withoutConsoleCapture(callPrevious);
  };
  errorUtils?.setGlobalHandler?.(handler);
  state.renderErrorSink = recordFatal;

  if (options.unhandledRejections) {
    const previousTracker = options.previousRejectionTracker;
    if (
      !previousTracker &&
      !state.warnedRejectionSlot &&
      isDevHost() &&
      typeof hermes()?.enablePromiseRejectionTracker === "function"
    ) {
      state.warnedRejectionSlot = true;
      warnInDev(
        () =>
          `${SDK_CONSOLE_PREFIX} init() takes over Hermes's only promise rejection tracker slot, and a tracker another library installed before it cannot be seen. If one exists, pass errors.previousRejectionTracker to keep it running, or errors.unhandledRejections: false to leave the slot alone.`,
      );
    }
    const tracker: RejectionTracker = {
      allRejections: true,
      onUnhandled: (id, rejection) => {
        if (active) {
          try {
            options.emit(errorEvent(rejection, "unhandledrejection"));
          } catch {
            // Never throw into the host.
          }
        }
        if (previousTracker) {
          notify(() => previousTracker.onUnhandled(id, rejection));
          return;
        }
        warnInDev(
          () =>
            `Possible unhandled promise rejection (id: ${id}):\n${describeRejection(rejection)}`,
        );
      },
      onHandled: (id) => {
        if (previousTracker) {
          notify(() => previousTracker.onHandled?.(id));
          return;
        }
        warnInDev(
          () =>
            `Promise rejection handled (id: ${id})\nThis means you can ignore any previous messages of the form "Possible unhandled promise rejection (id: ${id}):"`,
        );
      },
    };
    try {
      hermes()?.enablePromiseRejectionTracker?.(tracker);
    } catch {
      // No tracker on this engine.
    }
  }

  return {
    teardown() {
      active = false;
      if (state.renderErrorSink === recordFatal) {
        state.renderErrorSink = undefined;
      }
      try {
        if (previous && errorUtils?.getGlobalHandler?.() === handler) {
          errorUtils.setGlobalHandler?.(previous);
        }
      } catch {
        // Best-effort restore.
      }
    },
  };
};
