export type RandomBytes = (length: number) => Uint8Array;

/**
 * Random bytes for session, trace, and gesture ids. Web Crypto where the host
 * has it; a seeded fallback where it does not (React Native without a
 * `crypto.getRandomValues` polyfill). The ids need uniqueness, not secrecy,
 * so the fallback is acceptable there and is never used where crypto exists.
 */
export const createRandomBytes = (): RandomBytes => {
  const cryptoApi = (
    globalThis as { crypto?: { getRandomValues?: (a: Uint8Array) => unknown } }
  ).crypto;
  const getRandomValues = cryptoApi?.getRandomValues;
  if (typeof getRandomValues === "function") {
    return (length) => {
      const bytes = new Uint8Array(length);
      getRandomValues.call(cryptoApi, bytes);
      return bytes;
    };
  }

  // xorshift128+ seeded from the clock and Math.random: enough entropy to
  // keep ids unique across launches, with no claim beyond that.
  let s0 = (Date.now() ^ 0x9e3779b9) >>> 0;
  let s1 = (Math.random() * 0xffffffff) >>> 0;
  return (length) => {
    const bytes = new Uint8Array(length);
    for (let i = 0; i < length; i += 1) {
      let x = s0;
      const y = s1;
      s0 = y;
      x ^= x << 23;
      x ^= x >>> 17;
      x ^= y ^ (y >>> 26);
      s1 = x >>> 0;
      bytes[i] = (s0 + s1) & 0xff;
    }
    return bytes;
  };
};

export const toHex = (bytes: Uint8Array): string =>
  Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");

export const randomHex = (
  randomBytes: RandomBytes,
  byteLength: number,
): string => toHex(randomBytes(byteLength));

export const newPrefixedId = (
  randomBytes: RandomBytes,
  prefix: string,
): string => `${prefix}_${Date.now().toString(36)}${randomHex(randomBytes, 8)}`;
