import { createMemoryStore, type SessionStore } from "@sazabi/client-sdk-core";
import type { StorageAdapter } from "./types";

/**
 * Storage adapters may be synchronous (MMKV) or promise-returning
 * (AsyncStorage). Every call here is best-effort: an adapter that throws or
 * rejects degrades the SDK to in-memory state and never surfaces to the app.
 */
export const readKey = async (
  adapter: StorageAdapter,
  key: string,
): Promise<string | null> => {
  try {
    const value = await adapter.getItem(key);
    return typeof value === "string" ? value : null;
  } catch {
    return null;
  }
};

export const isThenable = (value: unknown): value is PromiseLike<unknown> =>
  typeof (value as { then?: unknown } | null | undefined)?.then === "function";

/** What a read found; `undefined` means the adapter failed to answer. */
export type ReadResult = { value: string | null } | undefined;

/**
 * Call the adapter and shape its answer, synchronously when it answers
 * synchronously (MMKV). A throw or rejection is `undefined`, never an
 * answer: the outbox must not delete a report it could not read.
 */
const callNow = <T>(
  call: () => unknown,
  shape: (value: unknown) => T,
): T | undefined | Promise<T | undefined> => {
  try {
    const value = call();
    return isThenable(value)
      ? Promise.resolve(value).then(shape, () => undefined)
      : shape(value);
  } catch {
    return undefined;
  }
};

/** Read a key, synchronously when the adapter can, so the crash outbox loads inside `init()`. */
export const readKeyNow = (
  adapter: StorageAdapter,
  key: string,
): ReadResult | Promise<ReadResult> =>
  callNow(
    () => adapter.getItem(key),
    (value): ReadResult => ({
      value: typeof value === "string" ? value : null,
    }),
  );

/**
 * Every key the adapter holds. `undefined` when the adapter has no listing
 * or it failed: the caller then knows only what the indexes list, never
 * that a key is absent.
 */
export const listKeysNow = (
  adapter: StorageAdapter,
): readonly string[] | undefined | Promise<readonly string[] | undefined> =>
  callNow(
    () => adapter.getAllKeys?.(),
    (value): readonly string[] | undefined =>
      Array.isArray(value)
        ? value.filter((key): key is string => typeof key === "string")
        : undefined,
  );

/**
 * `true` once the adapter accepted the write, `false` when it refused. A
 * synchronous adapter answers synchronously, which is how the crash path
 * knows the batch is on disk before the process can die.
 */
export const writeKey = (
  adapter: StorageAdapter,
  key: string,
  value: string,
): boolean | Promise<boolean> => {
  try {
    const result = adapter.setItem(key, value);
    return isThenable(result)
      ? Promise.resolve(result).then(
          () => true,
          () => false,
        )
      : true;
  } catch {
    // Persistence is best-effort; the caller decides what a refusal costs.
    return false;
  }
};

/** `true` once the adapter accepted the removal, synchronously when it can. */
export const removeKey = (
  adapter: StorageAdapter,
  key: string,
): boolean | Promise<boolean> => {
  try {
    const result = adapter.removeItem(key);
    return isThenable(result)
      ? Promise.resolve(result).then(
          () => true,
          () => false,
        )
      : true;
  } catch {
    // Persistence is best-effort.
    return false;
  }
};

export interface HydratingStore {
  /** Synchronous view the session machine reads through. */
  store: SessionStore;
  /** Resolves once every key has been read from the adapter. */
  ready: Promise<void>;
}

/**
 * The session machine needs synchronous reads, so persisted state is read
 * once into an in-memory mirror and every later write goes through to the
 * adapter. A key written locally before hydration finishes keeps the local
 * value: a `reset()` must not be undone by a slow read of the old identity.
 */
export const createHydratingStore = (
  adapter: StorageAdapter,
  keys: readonly string[],
): HydratingStore => {
  const mirror = createMemoryStore();
  const writtenLocally = new Set<string>();

  const ready = (async () => {
    for (const key of keys) {
      const value = await readKey(adapter, key);
      if (value !== null && !writtenLocally.has(key)) {
        mirror.set(key, value);
      }
    }
  })();

  return {
    store: {
      get: (key) => mirror.get(key),
      set(key, value) {
        mirror.set(key, value);
        writtenLocally.add(key);
        void writeKey(adapter, key, value);
      },
      remove(key) {
        mirror.remove(key);
        writtenLocally.add(key);
        void removeKey(adapter, key);
      },
    },
    ready,
  };
};
