import type { PointerTarget, PointerTracker } from "@sazabi/client-sdk-core";
import { Component, createElement, type ReactNode } from "react";
import { type GestureResponderEvent, View } from "react-native";
import { captureRenderError } from "./errors";
import { state } from "./process-state";

/**
 * Touch capture for the pointer-episode tracker. `<SazabiRoot>` is a plain
 * `View` that observes every touch bubbling up from the app without claiming
 * the responder, so gestures reach their targets untouched. It works
 * wherever it is mounted and whenever `init()` runs: touches before activation
 * are dropped, never queued.
 */

// The tracker lives in the process-wide state, so a `<SazabiRoot>` imported
// from a second copy of the module feeds the running instance.
export const setActiveTracker = (tracker: PointerTracker | undefined): void => {
  state.tracker = tracker;
};

// ------------------------------------------------------ target naming -----
// React Native exposes no DOM, so the widget under a touch is found by
// walking the React fiber the synthetic event carries. This reads React
// internals (the same ones Sentry's TouchEventBoundary reads) and is guarded:
// when the shape drifts, the episode still emits, without a name.

interface FiberLike {
  memoizedProps?: Record<string, unknown> | null;
  type?: unknown;
  elementType?: unknown;
  return?: FiberLike | null;
}

const MAX_FIBER_DEPTH = 60;
const MAX_PATH_SEGMENTS = 3;
const MAX_NAME_CHARS = 64;
const NAME_PROP = "sazabiName";
const MASK_PROP = "sazabiMask";
const INTERACTIVE_ROLES = new Set([
  "button",
  "link",
  "tab",
  "menuitem",
  "checkbox",
  "radio",
  "switch",
  "togglebutton",
  "imagebutton",
  "searchbox",
]);

const normalizeName = (raw: unknown): string | undefined => {
  if (typeof raw !== "string") return undefined;
  const collapsed = raw.replace(/\s+/g, " ").trim();
  if (!collapsed) return undefined;
  return collapsed.length > MAX_NAME_CHARS
    ? `${collapsed.slice(0, MAX_NAME_CHARS)}…`
    : collapsed;
};

const componentName = (fiber: FiberLike): string | undefined => {
  const type = fiber.type ?? fiber.elementType;
  if (typeof type === "function") {
    const named = type as { displayName?: string; name?: string };
    return normalizeName(named.displayName || named.name);
  }
  if (typeof type === "object" && type !== null) {
    // forwardRef / memo wrappers carry the inner component.
    const wrapped =
      (type as { render?: unknown; type?: unknown }).render ??
      (type as { type?: unknown }).type;
    if (typeof wrapped === "function") {
      const named = wrapped as { displayName?: string; name?: string };
      return normalizeName(named.displayName || named.name);
    }
  }
  return undefined;
};

export const describeFiberTarget = (
  targetInstance: unknown,
): PointerTarget | undefined => {
  try {
    let fiber = targetInstance as FiberLike | null | undefined;
    if (!fiber || typeof fiber !== "object") return undefined;

    let name: string | undefined;
    let masked = false;
    let interactive = false;
    const path: string[] = [];

    for (let depth = 0; fiber && depth < MAX_FIBER_DEPTH; depth += 1) {
      const props = fiber.memoizedProps ?? undefined;
      if (props) {
        if (props[MASK_PROP]) masked = true;
        if (name === undefined) {
          name =
            normalizeName(props[NAME_PROP]) ??
            normalizeName(props.accessibilityLabel) ??
            normalizeName(props.testID);
        }
        if (
          typeof props.onPress === "function" ||
          typeof props.onPressIn === "function" ||
          (typeof props.accessibilityRole === "string" &&
            INTERACTIVE_ROLES.has(props.accessibilityRole)) ||
          (typeof props.role === "string" && INTERACTIVE_ROLES.has(props.role))
        ) {
          interactive = true;
        }
      }
      if (path.length < MAX_PATH_SEGMENTS) {
        const segment = componentName(fiber);
        if (segment && segment !== "SazabiRoot") path.unshift(segment);
      }
      fiber = fiber.return;
    }

    return {
      id: path.length > 0 ? path.join(" > ") : undefined,
      name: masked ? undefined : name,
      tag: path[path.length - 1],
      interactive,
    };
  } catch {
    return undefined;
  }
};

// --------------------------------------------------------- touch events --

type ResponderEvent = GestureResponderEvent & { _targetInst?: unknown };

const onTouchStart = (event: ResponderEvent): void => {
  const tracker = state.tracker;
  if (!tracker) return;
  try {
    const { changedTouches, touches } = event.nativeEvent;
    const target = describeFiberTarget(event._targetInst);
    for (const touch of changedTouches) {
      tracker.down({
        id: touch.identifier,
        type: "touch",
        primary: touches.length <= 1,
        x: touch.pageX,
        y: touch.pageY,
        pressure: touch.force || undefined,
        target,
      });
    }
  } catch {
    // Capture failures must never surface to the host.
  }
};

const onTouchMove = (event: ResponderEvent): void => {
  const tracker = state.tracker;
  if (!tracker) return;
  try {
    for (const touch of event.nativeEvent.changedTouches) {
      tracker.move(
        touch.identifier,
        touch.pageX,
        touch.pageY,
        touch.force || undefined,
      );
    }
  } catch {
    // Ignore.
  }
};

const onTouchEnd = (event: ResponderEvent): void => {
  const tracker = state.tracker;
  if (!tracker) return;
  try {
    for (const touch of event.nativeEvent.changedTouches) {
      tracker.up(touch.identifier, touch.pageX, touch.pageY);
    }
  } catch {
    // Ignore.
  }
};

// On Android a native ScrollView that intercepts a drag sends one cancel and
// then nothing more for that touch, so the episode ends at the handoff.
const onTouchCancel = (event: ResponderEvent): void => {
  const tracker = state.tracker;
  if (!tracker) return;
  try {
    for (const touch of event.nativeEvent.changedTouches) {
      tracker.cancel(touch.identifier);
    }
  } catch {
    // Ignore.
  }
};

const ROOT_STYLE = { flex: 1 };

/**
 * Wrap the app's root in this once, outside every other component. It
 * renders a single full-size `View` with touch observers, and is the error
 * boundary that records a render or commit error as a `fatal` row (crash
 * outbox included) before rethrowing it: under React 19 such an error never
 * reaches `ErrorUtils`, so without this boundary a release app dies with
 * nothing recorded. The rethrow leaves React Native's own handling (the red
 * box in development, the native crash in release) exactly as it was.
 */
export class SazabiRoot extends Component<
  { children?: ReactNode },
  { error?: { value: unknown } }
> {
  static displayName = "SazabiRoot";

  state: { error?: { value: unknown } } = {};

  static getDerivedStateFromError(error: unknown): {
    error: { value: unknown };
  } {
    // Render phase, before React reports anything: the row and the outbox
    // are written while the process is certainly still alive. A repeat call
    // from a retried render is recorded once.
    captureRenderError(error);
    return { error: { value: error } };
  }

  render(): ReturnType<typeof createElement> {
    const failed = this.state.error;
    if (failed) {
      // Rethrown during the boundary's own render, so React treats it as
      // uncaught: no `onCaughtError` report, the fatal path runs as it would
      // without the SDK.
      throw failed.value;
    }
    return createElement(
      View,
      {
        style: ROOT_STYLE,
        collapsable: false,
        onTouchStart,
        onTouchMove,
        onTouchEnd,
        onTouchCancel,
      },
      this.props.children,
    );
  }
}
